const isCJK = (char) => {
  return /^[\p{Unified_Ideograph}\u0800-\u9FFC]+$/u.test(char);
};

function localName(el) {
  return el.localName || el.tagName.split(":").pop() || el.tagName;
}
const NS = {
  TT: "http://www.w3.org/ns/ttml",
  TTM: "http://www.w3.org/ns/ttml#metadata",
  ITUNES: "http://music.apple.com/lyric-ttml-internal",
  AMLL: "http://www.example.com/ns/amll",
  XML: "http://www.w3.org/XML/1998/namespace",
  TTS: "http://www.w3.org/ns/ttml#styling",
};

function getAttrNS(el, ns, name, fallbackAttrName) {
  if (!el || typeof el.hasAttributes !== "function" || !el.hasAttributes()) return null;
  if (ns && typeof el.getAttributeNS === "function") {
    try {
      const val = el.getAttributeNS(ns, name);
      if (val !== null && val !== "") return val;
    } catch (e) {  }
  }
  const direct = el.getAttribute(name);
  if (direct !== null && direct !== "") return direct;
  if (fallbackAttrName) {
    const val = el.getAttribute(fallbackAttrName);
    if (val !== null && val !== "") return val;
  }
  for (const attr of Array.from(el.attributes)) {
    const attrLocal = attr.localName || (attr.nodeName ? attr.nodeName.split(":").pop() : "");
    if (attrLocal === name) return attr.value;
  }
}

const TIME_REGEX = /^(?:(?:(\d+):)?(\d+):)?(\d+(?:\.\d+)?)$/;

function parseTime(value) {
  if (value === null || value === undefined) return 0;
  const text = String(value).trim();
  if (!text) return 0;
  if (text.endsWith("s") && !text.includes(":")) {
    const seconds = Number(text.slice(0, -1));
    if (!Number.isFinite(seconds)) return 0;
    return Math.round(seconds * 1000);
  }
  const match = text.match(TIME_REGEX);
  if (match) {
    const sec = Number(match[3] || "0");
    const min = match[2] ? parseInt(match[2], 10) : 0;
    const hr = match[1] ? parseInt(match[1], 10) : 0;
    if (Number.isFinite(sec) && Number.isFinite(min) && Number.isFinite(hr)) {
      const totalSeconds = hr * 3600 + min * 60 + sec;
      return Math.round(totalSeconds * 1000);
    }
  }
  return parseTimespan(text);
}

function parseTimespan(value) {
  if (!value) return 0;
  const text = value.trim();
  if (!text) return 0;
  if (text.endsWith("s") && !text.includes(":")) {
    const seconds = Number(text.slice(0, -1));
    if (!Number.isFinite(seconds)) return 0;
    return Math.round(seconds * 1000);
  }
  const parts = text.split(":");
  const last = parts[parts.length - 1] ?? "0";
  const [secStr, fracStr] = last.split(".");
  const seconds = Number(secStr || "0");
  const milliseconds = fracStr !== undefined
    ? Number(fracStr.padEnd(3, "0").slice(0, 3))
    : 0;
  let minutes = 0, hours = 0;
  if (parts.length === 2) minutes = Number(parts[0] || "0");
  else if (parts.length >= 3) {
    hours = Number(parts[0] || "0");
    minutes = Number(parts[1] || "0");
  }
  if (!Number.isFinite(seconds) || !Number.isFinite(milliseconds) ||
      !Number.isFinite(minutes) || !Number.isFinite(hours)) return 0;
  return ((hours * 60 + minutes) * 60 + seconds) * 1000 + milliseconds;
}

function normalizeText(text, trim = true) {
  if (text === null || text === undefined) return "";
  let result = String(text).replace(/\s+/g, " ");
  if (trim) result = result.trim();
  return result;
}

function isFormattingWhitespace(text) {
  if (!text) return false;
  return text.includes("\n") && text.trim().length === 0;
}
function parseSpanNode(spanEl) {
  const span = {
    text: "",
    begin: getAttrNS(spanEl, NS.XML, "begin", "begin"),
    end: getAttrNS(spanEl, NS.XML, "end", "end"),
    role: getAttrNS(spanEl, NS.TTM, "role", "ttm:role"),
    lang: getAttrNS(spanEl, NS.XML, "lang", "xml:lang"),
    ruby: getAttrNS(spanEl, NS.TTS, "ruby", "tts:ruby"),
    obscene: getAttrNS(spanEl, NS.AMLL, "obscene", "amll:obscene"),
    emptyBeat: getAttrNS(spanEl, NS.AMLL, "empty-beat", "amll:empty-beat"),
    children: [],
    tail: ""
  };
  let lastChild = null;
  for (const node of Array.from(spanEl.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) {
      const text = node.textContent ?? "";
      if (lastChild) lastChild.tail += text;
      else span.text += text;
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      if (localName(node) === "span") {
        const child = parseSpanNode(node);
        span.children.push(child);
        lastChild = child;
      }
    }
  }
  return span;
}

function flattenSpanText(span, skipRoles) {
  const skipCurrent = span.role ? skipRoles?.has(span.role) : false;
  let text = "";
  if (!skipCurrent) {
    text += span.text || "";
    for (const child of span.children) {
      text += flattenSpanText(child, skipRoles);
    }
  }
  text += span.tail || "";
  return text;
}

function flattenSpanInnerText(span, skipRoles) {
  const skipCurrent = span.role ? skipRoles?.has(span.role) : false;
  let text = "";
  if (!skipCurrent) {
    text += span.text || "";
    for (const child of span.children) {
      text += flattenSpanText(child, skipRoles);
    }
  }
  return text;
}

function createWordFromSpanElement(wordEl, lineStartTime, lineEndTime, nextWordStartTime) {
  const begin = getAttrNS(wordEl, NS.XML, "begin", "begin");
  let end = getAttrNS(wordEl, NS.XML, "end", "end");

  const spanNode = parseSpanNode(wordEl);
  const skipRoles = new Set(["x-translation", "x-roman"]);

  if (spanNode.ruby === "container") {
    const baseSpan = spanNode.children.find(c => c.ruby === "base");
    const baseText = baseSpan
      ? flattenSpanInnerText(baseSpan, skipRoles)
      : flattenSpanInnerText(spanNode, skipRoles);
    const containerStart = begin ? parseTime(begin) : null;
    const containerEnd = end ? parseTime(end) : null;
    const baseStart = baseSpan && baseSpan.begin ? parseTime(baseSpan.begin) : null;
    const baseEnd = baseSpan && baseSpan.end ? parseTime(baseSpan.end) : null;
    const rubyWords = [];
    function collectRubyText(s, results) {
      if (s.ruby === "text") results.push(s);
      for (const c of s.children) collectRubyText(c, results);
    }
    const rubyTextSpans = [];
    collectRubyText(spanNode, rubyTextSpans);
    for (const rubySpan of rubyTextSpans) {
      const rubyBegin = rubySpan.begin ? parseTime(rubySpan.begin) : (containerStart ?? baseStart ?? 0);
      const rubyEnd = rubySpan.end ? parseTime(rubySpan.end) : (containerEnd ?? baseEnd ?? 0);
      rubyWords.push({
        word: flattenSpanInnerText(rubySpan, skipRoles),
        startTime: rubyBegin,
        endTime: rubyEnd
      });
    }
    const filtered = rubyWords.filter(w => w.word.trim().length > 0);
    const rubyStart = filtered.length > 0
      ? filtered.reduce((p, c) => Math.min(p, c.startTime), Infinity)
      : 0;
    const rubyEnd = filtered.reduce((p, c) => Math.max(p, c.endTime), 0);
    return {
      word: baseText,
      startTime: containerStart ?? baseStart ?? rubyStart,
      endTime: containerEnd ?? baseEnd ?? rubyEnd,
      obscene: spanNode.obscene === "true",
      emptyBeat: spanNode.emptyBeat ? (parseInt(spanNode.emptyBeat, 10) || 0) : 0,
      romanWord: "",
      ruby: rubyWords.length > 0 ? rubyWords : undefined
    };
  }

  if (!begin) {
    const wordText = flattenSpanInnerText(spanNode, skipRoles);
    if (!wordText || !wordText.trim()) return null;
    if (lineStartTime !== undefined && lineEndTime !== undefined && (lineStartTime > 0 || lineEndTime > 0)) {
      return {
        word: wordText,
        startTime: lineStartTime || 0,
        endTime: lineEndTime || 0,
        obscene: spanNode.obscene === "true",
        emptyBeat: spanNode.emptyBeat ? (parseInt(spanNode.emptyBeat, 10) || 0) : 0,
        romanWord: ""
      };
    }
    return {
      word: wordText,
      startTime: 0,
      endTime: 0,
      obscene: spanNode.obscene === "true",
      emptyBeat: spanNode.emptyBeat ? (parseInt(spanNode.emptyBeat, 10) || 0) : 0,
      romanWord: ""
    };
  }

  if (!end) {
    if (nextWordStartTime !== undefined && Number.isFinite(nextWordStartTime) && nextWordStartTime > 0) {
      end = `${nextWordStartTime / 1000}s`;
    } else if (lineEndTime && lineEndTime > 0) {
      end = `${lineEndTime / 1000}s`;
    } else {
      const beginMs = parseTime(begin);
      end = `${(beginMs + 1000) / 1000}s`;
    }
  }

  const wordText = flattenSpanInnerText(spanNode, skipRoles);
  if (!wordText || !wordText.trim()) return null;
  return {
    word: wordText,
    startTime: parseTime(begin),
    endTime: parseTime(end),
    obscene: spanNode.obscene === "true",
    emptyBeat: spanNode.emptyBeat ? (parseInt(spanNode.emptyBeat, 10) || 0) : 0,
    romanWord: ""
  };
}

function parseSidecarTextContent(textEl) {
  let fullText = "";
  const words = [];
  const bgWords = [];

  function pushSyllable(target, normalized, begin, end) {
    const startsWithSpace = /^\s/.test(normalized);
    const endsWithSpace = /\s$/.test(normalized);
    const cleanText = normalized.trim();
    if (startsWithSpace && target.length > 0) {
      target[target.length - 1].endsWithSpace = true;
    }
    if (cleanText.length > 0) {
      target.push({
        text: cleanText,
        startTime: parseTime(begin),
        endTime: parseTime(end),
        endsWithSpace: endsWithSpace
      });
    }
  }

  for (const node of Array.from(textEl.childNodes)) {
    if (node.nodeType === Node.TEXT_NODE) {
      const rawText = node.textContent || "";
      if (rawText.includes("\n") && rawText.trim().length === 0) continue;
      fullText += normalizeText(rawText, false);
    } else if (node.nodeType === Node.ELEMENT_NODE && localName(node) === "span") {
      const role = getAttrNS(node, NS.TTM, "role", "ttm:role");
      if (role === "x-translation" || role === "x-roman") continue;
      const begin = getAttrNS(node, NS.XML, "begin", "begin");
      const end = getAttrNS(node, NS.XML, "end", "end");
      const normalized = normalizeText(node.textContent || "", false);
      fullText += normalized;
      if (begin && end) {
        pushSyllable(role === "x-bg" ? bgWords : words, normalized, begin, end);
      }
    }
  }

  if (words.length === 1 && words[0].startTime === 0 && words[0].endTime === 0) {
    words.length = 0;
  }
  if (bgWords.length === 1 && bgWords[0].startTime === 0 && bgWords[0].endTime === 0) {
    bgWords.length = 0;
  }

  return { text: normalizeText(fullText), words, bgWords };
}

function alignRomanization(amllWords, romanWords) {
  let romanSearchStartIndex = 0;
  const MIN_IOU_THRESHOLD = 0.1;
  const FAST_TRACK_TOLERANCE_MS = 2;

  for (let i = 0; i < amllWords.length; i++) {
    const main = amllWords[i];
    if (!main.word || main.word.trim().length === 0) continue;
    const mainEndTime = main.endTime;
    let maxIou = 0;
    let bestMatchIndex = -1;
    let isFastTrackMatched = false;
    let j = romanSearchStartIndex;
    while (j < romanWords.length) {
      const sub = romanWords[j];
      if (Math.abs(main.startTime - sub.startTime) <= FAST_TRACK_TOLERANCE_MS) {
        main.romanWord = sub.text;
        romanSearchStartIndex = j + 1;
        isFastTrackMatched = true;
        break;
      }
      const subEndTime = sub.endTime;
      const overlapStart = Math.max(main.startTime, sub.startTime);
      const overlapEnd = Math.min(mainEndTime, subEndTime);
      const intersection = Math.max(0, overlapEnd - overlapStart);
      if (intersection > 0) {
        const unionStart = Math.min(main.startTime, sub.startTime);
        const unionEnd = Math.max(mainEndTime, subEndTime);
        const unionDuration = Math.max(1, unionEnd - unionStart);

        const iou = intersection / unionDuration;

        if (iou > maxIou) {
          maxIou = iou;
          bestMatchIndex = j;
        }
      }

      if (sub.startTime >= mainEndTime) {
        break;
      }
      j++;
    }

    if (
      !isFastTrackMatched &&
      bestMatchIndex !== -1 &&
      maxIou >= MIN_IOU_THRESHOLD
    ) {
      main.romanWord = romanWords[bestMatchIndex].text;
      romanSearchStartIndex = bestMatchIndex + 1;
    }
  }
}

function realWordsOfLine(line) {
  return line.words.filter(w => w.word && w.word.trim().length > 0);
}

function forceAlignByIndex(words, romanWords) {
  let k = 0;
  for (const w of words) {
    if (!w.word || w.word.trim().length === 0) continue;
    if (k >= romanWords.length) break;
    w.romanWord = romanWords[k].text;
    k++;
  }
}

function detectRomanOffsetMs(romanPairs) {
  const diffs = [];
  for (const { line, romanWords } of romanPairs) {
    const realWords = realWordsOfLine(line);
    if (realWords.length !== romanWords.length) continue;
    for (let i = 0; i < realWords.length; i++) {
      const rb = romanWords[i].startTime;
      const wb = realWords[i].startTime;
      if (rb == null || wb == null) continue;
      diffs.push(rb - wb);
    }
  }
  if (diffs.length === 0) return 0;
  const counter = new Map();
  for (const d of diffs) counter.set(d, (counter.get(d) ?? 0) + 1);
  const keys = Array.from(counter.keys()).sort((a, b) => (Math.abs(a) - Math.abs(b)) || (a - b));
  let mode = 0;
  let modeCount = 0;
  for (const k of keys) {
    if (counter.get(k) > modeCount) { mode = k; modeCount = counter.get(k); }
  }
  if (Math.abs(mode) <= 2) return 0;
  if (modeCount / diffs.length < 0.5) return 0;
  return mode;
}

function applyRomanizationRepair(lyricLines, sidecar) {
  const romanPairs = [];
  for (const line of lyricLines) {
    if (line.romanLyric) continue;
    if (!line.itunesKey || !sidecar[line.itunesKey]) continue;
    const sc = sidecar[line.itunesKey];
    if (!sc.romanizations || sc.romanizations.length === 0) continue;
    const roman = sc.romanizations[0];
    const romanWords = line.isBG
      ? (roman.bgWords ?? roman.words)
      : (roman.words ?? roman.bgWords);
    if (!romanWords || romanWords.length === 0) {
      if (roman.text) line.romanLyric = roman.text;
      continue;
    }
    romanPairs.push({ line, romanWords });
  }
  if (romanPairs.length === 0) return;

  const offsetMs = detectRomanOffsetMs(romanPairs);
  for (const { line, romanWords } of romanPairs) {
    const realWords = realWordsOfLine(line);
    if (realWords.length === romanWords.length) {
      forceAlignByIndex(line.words, romanWords);
    } else if (offsetMs !== 0) {
      const adjusted = romanWords.map(r => ({
        ...r,
        startTime: (r.startTime ?? 0) - offsetMs,
        endTime: (r.endTime ?? 0) - offsetMs,
      }));
      alignRomanization(line.words, adjusted);
    } else {
      alignRomanization(line.words, romanWords);
    }
  }
}

function parseTTML(ttmlText) {
  const parser = new DOMParser();
  const ttmlDoc = parser.parseFromString(ttmlText, "application/xml");

  const parseError = ttmlDoc.querySelector("parsererror");
  if (parseError) {
    console.error("TTML 解析错误", parseError.textContent);
    return { metadata: [], lyricLines: [] };
  }

  const agents = new Map();
  let mainAgentId = "v1";
  let mainAgentPicked = false;
  const allElements = Array.from(ttmlDoc.getElementsByTagName("*"));
  for (const el of allElements) {
    if (localName(el) !== "agent") continue;
    let p = el.parentElement;
    let inHead = false;
    while (p) {
      if (localName(p) === "head") { inHead = true; break; }
      p = p.parentElement;
    }
    if (!inHead) continue;

    const id = getAttrNS(el, NS.XML, "id", "xml:id") || getAttrNS(el, null, "id", null);
    if (!id) continue;
    const type = getAttrNS(el, NS.TTM, "type", "ttm:type") || "person";

    let name = "";
    for (const child of Array.from(el.getElementsByTagName("*"))) {
      if (localName(child) === "name") {
        name = (child.textContent || "").trim();
        break;
      }
    }
    agents.set(id, { type, name });

    if (type === "person" && !mainAgentPicked) {
      mainAgentId = id;
      mainAgentPicked = true;
    }
  }
  if (!agents.has("v1")) agents.set("v1", { type: "person", name: "" });
  if (!agents.has("v2")) agents.set("v2", { type: "other", name: "" });

  const metadata = [];
  function pushMeta(key, value) {
    if (key && value) metadata.push([key, value]);
  }

  for (const el of allElements) {
    if (localName(el) !== "meta") continue;
    const key = getAttrNS(el, NS.AMLL, "key", "amll:key");
    const value = getAttrNS(el, NS.AMLL, "value", "amll:value");
    if (key && value) pushMeta(key, value);
  }

  for (const el of allElements) {
    if (localName(el) === "title") {
      const text = (el.textContent || "").trim();
      if (text) { pushMeta("title", text); break; }
    }
  }

  const sidecar = {};
  const songwriters = [];

  for (const el of allElements) {
    if (localName(el) !== "iTunesMetadata") continue;
    for (const child of Array.from(el.getElementsByTagName("*"))) {
      if (localName(child) === "songwriter") {
        const name = (child.textContent || "").trim();
        if (name) songwriters.push(name);
      }
    }
    for (const container of Array.from(el.getElementsByTagName("*"))) {
      const containerName = localName(container);
      if (containerName !== "translations" && containerName !== "transliterations") continue;
      const type = containerName === "translations" ? "translations" : "romanizations";
      for (const item of Array.from(container.getElementsByTagName("*"))) {
        const itemName = localName(item);
        if (itemName !== "translation" && itemName !== "transliteration") continue;
        const lang = getAttrNS(item, NS.XML, "lang", "xml:lang");
        for (const textEl of Array.from(item.getElementsByTagName("*"))) {
          if (localName(textEl) !== "text") continue;
          const forId = getAttrNS(textEl, null, "for", null);
          if (!forId) continue;
          const content = parseSidecarTextContent(textEl);
          if (!content.text && content.words.length === 0 && content.bgWords.length === 0) continue;
          sidecar[forId] ??= { translations: [], romanizations: [] };
          sidecar[forId][type].push({
            language: lang || "",
            text: content.text,
            words: content.words.length > 0 ? content.words : undefined,
            bgWords: content.bgWords.length > 0 ? content.bgWords : undefined
          });
        }
      }
    }
  }

  for (const writer of songwriters) {
    pushMeta("songwriter", writer);
  }

  const body = allElements.find(el => localName(el) === "body");
  if (!body) return { metadata, lyricLines: [] };

  const lineEls = [];
  for (const el of Array.from(body.getElementsByTagName("*"))) {
    if (localName(el) === "p") {
      const begin = getAttrNS(el, NS.XML, "begin", "begin");
      const end = getAttrNS(el, NS.XML, "end", "end");
      lineEls.push({ el, begin, end });
    }
  }

  for (let i = 0; i < lineEls.length; i++) {
    const cur = lineEls[i];
    if (!cur.end) {
      if (i + 1 < lineEls.length) {
        const next = lineEls[i + 1];
        if (next.begin) {
          cur.end = next.begin;
          cur.endInferred = true;
        }
      }
      if (!cur.end && cur.begin) {
        const beginMs = parseTime(cur.begin);
        cur.end = `${(beginMs + 5000) / 1000}s`;
        cur.endInferred = true;
      }
    }
    if (!cur.begin && cur.end) {
      if (i > 0) {
        const prev = lineEls[i - 1];
        if (prev.end) cur.begin = prev.end;
      }
      if (!cur.begin) cur.begin = "0s";
    }
  }

  const lyricLines = [];
  let lastPersonAgentId = null;
  let lastPersonIsDuet = false;

  function parseLineElement(lineInfo, isBG, isDuet, parentItunesKey) {
    const lineEl = lineInfo.el;
    const startTimeAttr = lineInfo.begin;
    const endTimeAttr = lineInfo.end;
    let parsedStartTime = startTimeAttr ? parseTime(startTimeAttr) : 0;
    let parsedEndTime = endTimeAttr ? parseTime(endTimeAttr) : 0;

    const agent = getAttrNS(lineEl, NS.TTM, "agent", "ttm:agent");
    const itunesKey = getAttrNS(lineEl, NS.ITUNES, "key", "itunes:key");
    const isMeta = !!getAttrNS(lineEl, NS.AMLL, "meta", "amll:meta");

    let lineIsDuet = isDuet;
    if (!isBG) {
      const agentId = agent || mainAgentId;
      const agentInfo = agents.get(agentId);
      const isGroup = agentInfo?.type === "group";
      const isOther = agentInfo?.type === "other";

      if (isGroup) {
        lineIsDuet = false;
      } else {
        if (lastPersonAgentId === null) {
          lineIsDuet = isOther;
          lastPersonAgentId = agentId;
          lastPersonIsDuet = lineIsDuet;
        } else if (lastPersonAgentId === agentId) {
          lineIsDuet = lastPersonIsDuet;
        } else {
          lineIsDuet = !lastPersonIsDuet;
          lastPersonAgentId = agentId;
          lastPersonIsDuet = lineIsDuet;
        }
      }
    }

    const line = {
      words: [],
      translatedLyric: "",
      romanLyric: "",
      isBG: !!isBG,
      isDuet: lineIsDuet,
      isMeta: isMeta,
      agent: agent || mainAgentId,
      startTime: parsedStartTime,
      endTime: parsedEndTime,
      itunesKey: itunesKey || parentItunesKey
    };
    let haveBg = false;

    const childEntries = [];
    for (const node of Array.from(lineEl.childNodes)) {
      if (node.nodeType === Node.TEXT_NODE) {
        childEntries.push({ node, isText: true });
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        if (localName(node) === "span") {
          childEntries.push({ node, isText: false, role: getAttrNS(node, NS.TTM, "role", "ttm:role") });
        }
      }
    }

    const spanBeginTimes = childEntries.map(e =>
      e.isText ? null : (() => {
        const b = getAttrNS(e.node, NS.XML, "begin", "begin");
        return b ? parseTime(b) : null;
      })()
    );

    for (let i = 0; i < childEntries.length; i++) {
      const entry = childEntries[i];
      if (entry.isText) {
        const rawText = entry.node.textContent ?? "";
        if (!rawText || isFormattingWhitespace(rawText)) continue;
        const text = normalizeText(rawText, false);
        if (!text) continue;
        if (text.trim().length > 0) {
          line.words.push({
            word: text,
            startTime: parsedStartTime > 0 || parsedEndTime > 0 ? parsedStartTime : 0,
            endTime: parsedStartTime > 0 || parsedEndTime > 0 ? parsedEndTime : 0,
            obscene: false,
            emptyBeat: 0,
            romanWord: ""
          });
        } else {
          let anchor = null;
          const prevWord = line.words[line.words.length - 1];
          if (prevWord && prevWord.endTime > 0) anchor = prevWord.endTime;
          if (anchor === null) {
            for (let j = i + 1; j < childEntries.length; j++) {
              if (!childEntries[j].isText && spanBeginTimes[j] !== null && spanBeginTimes[j] > 0) {
                anchor = spanBeginTimes[j];
                break;
              }
            }
          }
          if (anchor === null) anchor = parsedStartTime > 0 ? parsedStartTime : 0;
          line.words.push({
            word: text,
            startTime: anchor,
            endTime: anchor,
            obscene: false,
            emptyBeat: 0,
            romanWord: ""
          });
        }
        continue;
      }

      const wordEl = entry.node;
      const role = entry.role;

      if (role === "x-bg") {
        const bgBegin = getAttrNS(wordEl, NS.XML, "begin", "begin");
        const bgEnd = getAttrNS(wordEl, NS.XML, "end", "end");
        parseLineElement({ el: wordEl, begin: bgBegin, end: bgEnd }, true, line.isDuet, line.itunesKey);
        // 元信息行(x-bg 在 meta 的 p 里)的背景行也按元信息算, 不参与滚动/聚焦/翻译匹配
        if (isMeta) {
          const bgLine = lyricLines[lyricLines.length - 1];
          if (bgLine) bgLine.isMeta = true;
        }
        haveBg = true;
      } else if (role === "x-translation") {
        if (!line.translatedLyric) line.translatedLyric = wordEl.textContent || "";
      } else if (role === "x-roman") {
        if (!line.romanLyric) line.romanLyric = wordEl.textContent || "";
      } else {
        let nextStart = null;
        for (let j = i + 1; j < spanBeginTimes.length; j++) {
          if (spanBeginTimes[j] !== null && spanBeginTimes[j] > 0) {
            nextStart = spanBeginTimes[j];
            break;
          }
        }
        const word = createWordFromSpanElement(
          wordEl,
          parsedStartTime,
          parsedEndTime,
          nextStart ?? undefined
        );
        if (word) {
          const creatorUrl = getAttrNS(wordEl, NS.AMLL, "url", "amll:url");
          if (creatorUrl) {
            word.url = creatorUrl;
            word.avatar = getAttrNS(wordEl, NS.AMLL, "avatar", "amll:avatar");
          }
          if (getAttrNS(wordEl, NS.AMLL, "keep", "amll:keep")) word.keep = true;
          line.words.push(word);
        }
      }
    }

    if (line.words.length > 0) {
      let minStart = Infinity;
      let maxEnd = 0;
      for (const w of line.words) {
        if (w.endTime < w.startTime) w.endTime = w.startTime;
        if (w.startTime < minStart) minStart = w.startTime;
        if (w.endTime > maxEnd) maxEnd = w.endTime;
      }
      if (line.startTime === 0 || (minStart !== Infinity && minStart > 0 && minStart < line.startTime)) {
        line.startTime = minStart === Infinity ? 0 : minStart;
      }
      if (line.endTime === 0 || maxEnd > line.endTime) {
        line.endTime = maxEnd;
      }
    }

    if (line.isBG) {
      const firstWord = line.words[0];
      if (firstWord && /^[（(]/.test(firstWord.word)) {
        firstWord.word = firstWord.word.substring(1);
        if (firstWord.word.length === 0) line.words.shift();
      }
      const lastWord = line.words[line.words.length - 1];
      if (lastWord && /[)）]$/.test(lastWord.word)) {
        lastWord.word = lastWord.word.substring(0, lastWord.word.length - 1);
        if (lastWord.word.length === 0) line.words.pop();
      }
    }

    if (line.words.length === 0 && (line.startTime > 0 || line.endTime > 0)) {
      const fullText = normalizeText(lineEl.textContent || "", true);
      if (fullText) {
        line.words.push({
          word: fullText,
          startTime: line.startTime,
          endTime: line.endTime,
          obscene: false,
          emptyBeat: 0,
          romanWord: ""
        });
      }
    }

    if (line.itunesKey && sidecar[line.itunesKey]) {
      const sc = sidecar[line.itunesKey];
      if (!line.translatedLyric && sc.translations.length > 0) {
        line.translatedLyric = sc.translations.map(t => t.text).join(" / ");
      }
    }

    if (haveBg) {
      const bgLine = lyricLines.pop();
      lyricLines.push(line);
      if (bgLine) lyricLines.push(bgLine);
    } else {
      lyricLines.push(line);
    }
  }

  for (const lineInfo of lineEls) {
    parseLineElement(lineInfo, false, false, null);
  }

  applyRomanizationRepair(lyricLines, sidecar);

  return { metadata, lyricLines };
}

function normalizeSpaces(lines) {
  for (const line of lines) {
    for (const word of line.words) {
      word.word = word.word.replace(/\s+/g, " ");
    }
  }
}

function resetLineTimestamps(lines) {
  for (const line of lines) {
    if (
      line.words.length === 1 &&
      line.words[0].startTime === 0 &&
      line.words[0].endTime === 0 &&
      (line.startTime !== 0 || line.endTime !== 0)
    ) {
      line.words[0].startTime = line.startTime;
      line.words[0].endTime = line.endTime;
    } else if (line.words.length > 0) {
      const firstWord = line.words[0];
      const lastWord = line.words[line.words.length - 1];
      line.startTime = firstWord.startTime;
      line.endTime = lastWord.endTime;
    }
  }
}

function convertExcessiveBackgroundLines(lines) {
  let consecutiveBgCount = 0;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.isBG) {
      consecutiveBgCount++;
      if (i === 0 || consecutiveBgCount > 1) {
        line.isBG = false;
      }
    } else {
      consecutiveBgCount = 0;
    }
  }
}

function syncMainAndBackgroundLines(lines) {
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i];
    if (line.isBG) continue;
    const nextLine = lines[i + 1];
    if (nextLine?.isBG) {
      const allWords = [...line.words, ...nextLine.words].filter(
        w => w.word.trim().length > 0
      );
      if (allWords.length > 0) {
        const finalStart = Math.min(
          line.startTime,
          nextLine.startTime,
          ...allWords.map(w => w.startTime)
        );
        const finalEnd = Math.max(
          line.endTime,
          nextLine.endTime,
          ...allWords.map(w => w.endTime)
        );
        line.startTime = finalStart;
        line.endTime = finalEnd;
        nextLine.startTime = finalStart;
        nextLine.endTime = finalEnd;
      }
    }
  }
}

function sortLyricLines(lines) {
  const groups = [];
  for (let i = 0; i < lines.length; i++) {
    const mainLine = lines[i];
    const groupLines = [mainLine];
    if (!mainLine.isBG && lines[i + 1]?.isBG) {
      groupLines.push(lines[++i]);
    }
    groups.push({
      lines: groupLines,
      startTime: mainLine.startTime,
      originalIndex: groups.length
    });
  }
  groups.sort((a, b) => {
    const timeDifference = a.startTime - b.startTime;
    return timeDifference || a.originalIndex - b.originalIndex;
  });
  let lineIndex = 0;
  for (const group of groups) {
    for (const line of group.lines) {
      lines[lineIndex++] = line;
    }
  }
}

function cleanUnintentionalOverlaps(lines, syncBackgroundLines) {
  for (let i = 0; i < lines.length - 1; i++) {
    const line = lines[i];
    if (line.isBG) continue;
    
    for (let j = i + 1; j < lines.length; j++) {
      const nextLine = lines[j];
      if (nextLine.isBG) continue;
      const overlap = line.endTime - nextLine.startTime;
      if (overlap <= 0) break;
      const nextDuration = nextLine.endTime - nextLine.startTime;
      const percentageThreshold = nextDuration * 0.1;
      const isIntentionalOverlap =
        overlap >= 500 || (overlap > 100 && overlap > percentageThreshold);
      if (!isIntentionalOverlap) {
        line.endTime = nextLine.startTime;
        const attachedBgLine = lines[i + 1];
        if (syncBackgroundLines && attachedBgLine?.isBG) {
          attachedBgLine.endTime = nextLine.startTime;
        }
        break;
      }
    }
  }
}


function tryAdvanceStartTime(lines, syncBackgroundLines) {
  const defaultAdvanceAmount = 600;
  const fallbackAdvanceAmount = 400;
  const fallbackAdvanceRatio = 0.7;

  let prevLineStartTime = 0;
  let prevLineEndTime = 0;
  let prevMainGroupStartTime = 0;
  let prevMainGroupEndTime = 0;
  let hasPrevLine = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.isBG) continue;

    const originalStartTime = line.startTime;
    const originalEndTime = line.endTime;

    let targetAdvanceAmount = 0;
    let safeBoundary = 0;

    if (hasPrevLine) {
      const originallyHadGap = originalStartTime >= prevLineEndTime;
      if (originallyHadGap) {
        
        targetAdvanceAmount = defaultAdvanceAmount;
        safeBoundary = prevMainGroupEndTime;
      } else {
        
        const overlapDuration = prevLineEndTime - originalStartTime;
        if (overlapDuration < fallbackAdvanceAmount) {
          targetAdvanceAmount = overlapDuration * fallbackAdvanceRatio;
        } else {
          targetAdvanceAmount = fallbackAdvanceAmount;
        }
        
        safeBoundary = prevLineStartTime;
      }
    } else {
      
      targetAdvanceAmount = defaultAdvanceAmount;
      safeBoundary = 0;
    }

    if (originalEndTime - originalStartTime <= 1) {
      targetAdvanceAmount = 0;
    }

    const targetTime = line.startTime - targetAdvanceAmount;
    const newStartTime = Math.max(safeBoundary, targetTime);
    if (newStartTime < line.startTime) {
      line.startTime = newStartTime;
    }

    
    const nextLine = lines[i + 1];
    if (syncBackgroundLines && nextLine?.isBG) {
      nextLine.startTime = line.startTime;
    }

    
    
    if (hasPrevLine) {
      const overlapsPrevGroup =
        originalStartTime < prevMainGroupEndTime &&
        originalEndTime > prevMainGroupStartTime;
      if (overlapsPrevGroup) {
        prevMainGroupStartTime = Math.min(prevMainGroupStartTime, originalStartTime);
        prevMainGroupEndTime = Math.max(prevMainGroupEndTime, originalEndTime);
      } else {
        prevMainGroupStartTime = originalStartTime;
        prevMainGroupEndTime = originalEndTime;
      }
    } else {
      prevMainGroupStartTime = originalStartTime;
      prevMainGroupEndTime = originalEndTime;
    }

    prevLineStartTime = line.startTime;
    prevLineEndTime = originalEndTime;
    hasPrevLine = true;
  }
}

function optimizeLyricLines(lines) {
  const syncBackgroundLines = true;
  normalizeSpaces(lines);
  resetLineTimestamps(lines);
  convertExcessiveBackgroundLines(lines);
  syncMainAndBackgroundLines(lines);
  sortLyricLines(lines);
  cleanUnintentionalOverlaps(lines, syncBackgroundLines);
  tryAdvanceStartTime(lines, syncBackgroundLines);
  return lines;
}


const SPLIT_WHITESPACE_RE = /(\s+)/;
const WHITESPACE_RE = /\s/g;

function chunkAndSplitLyricWords(words) {
  const result = [];
  let currentGroup = [];

  const flushGroup = () => {
    if (currentGroup.length > 0) {
      result.push(currentGroup.length === 1 ? currentGroup[0] : [...currentGroup]);
      currentGroup = [];
    }
  };

  const processAtom = (atom) => {
    const isSpace = atom.word.trim().length === 0;
    const hasRuby = (atom.ruby?.length ?? 0) > 0;
    const isCJKChar = isCJK(atom.word);
    
    const isMergeable = !isSpace && !hasRuby && !isCJKChar;
    if (isMergeable) {
      currentGroup.push(atom);
    } else {
      flushGroup();
      result.push(atom);
    }
  };

  for (const w of words) {
    const content = w.word.trim();
    const isSpace = content.length === 0;
    const romanWord = w.romanWord ?? "";
    const obscene = w.obscene ?? false;
    const hasRuby = (w.ruby?.length ?? 0) > 0;

    if (isSpace) {
      processAtom({ ...w, obscene });
      continue;
    }

    if (hasRuby) {
      const leadingSpaceMatch = w.word.match(/^\s+/);
      const trailingSpaceMatch = w.word.match(/\s+$/);
      const leadingSpace = leadingSpaceMatch ? leadingSpaceMatch[0] : "";
      const trailingSpace = trailingSpaceMatch ? trailingSpaceMatch[0] : "";
      if (leadingSpace) {
        processAtom({
          word: leadingSpace,
          romanWord: "",
          startTime: w.startTime,
          endTime: w.startTime,
          obscene: obscene
        });
      }
      processAtom({ ...w, word: content, obscene: obscene });
      if (trailingSpace) {
        processAtom({
          word: trailingSpace,
          romanWord: "",
          startTime: w.endTime,
          endTime: w.endTime,
          obscene: obscene
        });
      }
      continue;
    }

    const parts = w.word.split(SPLIT_WHITESPACE_RE).filter(p => p.length > 0);
    const totalLength = w.word.replace(WHITESPACE_RE, "").length || 1;
    const timeSpan = w.endTime - w.startTime;
    const timePerUnit = timeSpan / totalLength;

    
    const wordParts = w.word.trim().split(/\s+/).filter(p => p.length > 0);
    const romanTrimmed = romanWord.trim();
    const romanParts = romanTrimmed.length > 0
      ? romanTrimmed.split(/\s+/).filter(p => p.length > 0)
      : [];
    const isMatched = wordParts.length > 0 && wordParts.length === romanParts.length;

    let currentOffset = 0;
    let nonSpaceIndex = 0;

    for (const part of parts) {
      if (!part.trim()) {
        const startTime = w.startTime + currentOffset * timePerUnit;
        processAtom({
          word: part,
          romanWord: "",
          startTime: startTime,
          endTime: startTime,
          obscene: obscene
        });
        continue;
      }

      let partRomanWord = "";
      if (romanParts.length > 0) {
        if (isMatched) {
          partRomanWord = romanParts[nonSpaceIndex] ?? "";
        } else if (nonSpaceIndex === 0) {
          partRomanWord = romanWord;
        }
      }
      nonSpaceIndex++;

      if (isCJK(part) && part.length > 1 && romanTrimmed.length === 0 && !w.keep) {
        const chars = part.split("");
        for (const char of chars) {
          const startTime = w.startTime + currentOffset * timePerUnit;
          processAtom({
            word: char,
            romanWord: "",
            startTime: startTime,
            endTime: startTime + timePerUnit,
            obscene: obscene,
            url: w.url,
            avatar: w.avatar
          });
          currentOffset += 1;
        }
      } else {
        const partRealLen = part.length;
        const startTime = w.startTime + currentOffset * timePerUnit;
        const duration = partRealLen * timePerUnit;
        processAtom({
          word: part,
          romanWord: partRomanWord,
          startTime: startTime,
          endTime: startTime + duration,
          obscene: obscene,
          url: w.url,
          avatar: w.avatar
        });
        currentOffset += partRealLen;
      }
    }
  }

  flushGroup();
  return result;
}

const clamp01 = (x) => Math.min(1, Math.max(0, x));
const clampPositive = (x) => Math.max(0, x);
const clampNum = (min, cur, max) => Math.max(min, Math.min(cur, max));



function makeBezier(x1, y1, x2, y2) {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const solveT = (x) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const cur = ((ax * t + bx) * t + cx) * t - x;
      const deriv = (3 * ax * t + 2 * bx) * t + cx;
      if (Math.abs(deriv) < 1e-6) break;
      t -= cur / deriv;
    }
    return t;
  };
  return (x) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    const t = solveT(x);
    return ((ay * t + by) * t + cy) * t;
  };
}







function solveSpring(from, velocity, to, delay, params) {
  const soft = params?.soft ?? false;
  const stiffness = params?.stiffness ?? 100;
  const damping = params?.damping ?? 10;
  const mass = params?.mass ?? 1;
  const delta = to - from;

  
  if (soft || 1.0 <= damping / (2.0 * Math.sqrt(stiffness * mass))) {
    const angular_frequency = -Math.sqrt(stiffness / mass);
    const leftover = -angular_frequency * delta - velocity;
    const pos = (t) => {
      t -= delay;
      if (t < 0) return from;
      return to - (delta + t * leftover) * Math.exp(t * angular_frequency);
    };
    const vel = (t) => {
      t -= delay;
      if (t < 0) return 0;
      return -(leftover + (delta + t * leftover) * angular_frequency) * Math.exp(t * angular_frequency);
    };
    const acc = (t) => {
      t -= delay;
      if (t < 0) return 0;
      
      const u = leftover + (delta + t * leftover) * angular_frequency;
      return -(leftover * angular_frequency + u * angular_frequency) * Math.exp(t * angular_frequency);
    };
    return { pos, vel, acc };
  }

  
  const damping_frequency = Math.sqrt(Math.max(0, 4.0 * mass * stiffness - damping ** 2.0));
  const leftover = (damping * delta - 2.0 * mass * velocity) / damping_frequency;
  const dfm = (0.5 * damping_frequency) / mass;
  const dm = -(0.5 * damping) / mass;

  const pos = (t) => {
    t -= delay;
    if (t < 0) return from;
    return to - (Math.cos(t * dfm) * delta + Math.sin(t * dfm) * leftover) * Math.exp(t * dm);
  };
  const vel = (t) => {
    t -= delay;
    if (t < 0) return 0;
    const cosVal = Math.cos(t * dfm);
    const sinVal = Math.sin(t * dfm);
    const u = cosVal * delta + sinVal * leftover;
    const du = -dfm * sinVal * delta + dfm * cosVal * leftover;
    return -(du + u * dm) * Math.exp(t * dm);
  };
  const acc = (t) => {
    t -= delay;
    if (t < 0) return 0;
    const cosVal = Math.cos(t * dfm);
    const sinVal = Math.sin(t * dfm);
    const u = cosVal * delta + sinVal * leftover;
    const du = -dfm * sinVal * delta + dfm * cosVal * leftover;
    const d2u = -dfm * dfm * u;
    return -(d2u + 2 * du * dm + u * dm * dm) * Math.exp(t * dm);
  };
  return { pos, vel, acc };
}

class Spring {
  constructor(currentPosition = 0, params = {}) {
    this.targetPosition = currentPosition;
    this.currentPosition = currentPosition;
    this.currentTime = 0;
    this.params = params;
    this.currentSolver = () => this.targetPosition;
    this.currentVelocity = () => 0;
    this.currentAcceleration = () => 0;
    this.queueParams = undefined;
    this.queuePosition = undefined;
  }
  resetSolver() {
    const curV = this.currentVelocity(this.currentTime);
    this.currentTime = 0;
    const solver = solveSpring(
      this.currentPosition, curV, this.targetPosition, 0, this.params);
    this.currentSolver = solver.pos;
    this.currentVelocity = solver.vel;
    this.currentAcceleration = solver.acc;
  }
  
  arrived() {
    return Math.abs(this.targetPosition - this.currentPosition) < 0.01 &&
      Math.abs(this.currentVelocity(this.currentTime)) < 0.01 &&
      Math.abs(this.currentAcceleration(this.currentTime)) < 0.01 &&
      this.queueParams === undefined &&
      this.queuePosition === undefined;
  }
  setPosition(targetPosition) {
    this.targetPosition = targetPosition;
    this.currentPosition = targetPosition;
    this.currentSolver = () => this.targetPosition;
    this.currentVelocity = () => 0;
    this.currentAcceleration = () => 0;
  }
  update(delta = 0) {
    this.currentTime += delta;
    this.currentPosition = this.currentSolver(this.currentTime);
    if (this.queueParams) {
      this.queueParams.time -= delta;
      if (this.queueParams.time <= 0) {
        const queued = this.queueParams;
        this.queueParams = undefined;
        this.params = { ...this.params, ...queued };
        this.resetSolver();
      }
    }
    if (this.queuePosition) {
      this.queuePosition.time -= delta;
      if (this.queuePosition.time <= 0) {
        const pos = this.queuePosition.position;
        this.queuePosition = undefined;
        this.setTargetPosition(pos);
      }
    }
    if (this.arrived()) this.setPosition(this.targetPosition);
  }
  setTargetPosition(targetPosition, delay = 0) {
    
    if (delay <= 0 && Math.abs(this.targetPosition - targetPosition) < 0.001) {
      this.queuePosition = undefined;
      return;
    }
    if (delay > 0) {
      this.queuePosition = { position: targetPosition, time: delay };
    } else {
      this.queuePosition = undefined;
      this.targetPosition = targetPosition;
      this.resetSolver();
    }
  }
  updateParams(params = {}) {
    this.params = { ...this.params, ...params };
    this.resetSolver();
  }
  getCurrentPosition() { return this.currentPosition; }
}



const SLOW_STIFFNESS = 90;
const SLOW_DAMPING = 15;

const MEDIUM_STIFFNESS = 140;
const MEDIUM_DAMPING = 22;

const SPRING_MIN_INTERVAL = 100;
const SPRING_MAX_INTERVAL = 800;
const SPRING_MIN_STIFFNESS = 170;
const SPRING_MAX_STIFFNESS = 220;
const SPRING_DAMPING_MULTIPLIER = 2.2;
const SPRING_INTERVAL_EXPONENT = 0.2;






function getPosYSpringPolicy(isSeeking, isInterludeActive, intervalMs, isEndOfSong = false) {
  if (isSeeking || isInterludeActive) {
    return { stiffness: SLOW_STIFFNESS, damping: SLOW_DAMPING };
  }
  if (isEndOfSong) {
    return { stiffness: MEDIUM_STIFFNESS, damping: MEDIUM_DAMPING };
  }
  if (intervalMs == null) {
    return { stiffness: SLOW_STIFFNESS, damping: SLOW_DAMPING };
  }
  const clampedInterval = Math.min(
    Math.max(intervalMs, SPRING_MIN_INTERVAL),
    SPRING_MAX_INTERVAL,
  );
  let ratio = 1 - (clampedInterval - SPRING_MIN_INTERVAL) / (SPRING_MAX_INTERVAL - SPRING_MIN_INTERVAL);
  
  ratio = ratio ** SPRING_INTERVAL_EXPONENT;
  const targetStiffness = SPRING_MIN_STIFFNESS + ratio * (SPRING_MAX_STIFFNESS - SPRING_MIN_STIFFNESS);
  const targetDamping = Math.sqrt(targetStiffness) * SPRING_DAMPING_MULTIPLIER;
  return { stiffness: targetStiffness, damping: targetDamping };
}


const POS_Y_SPRING_DEFAULT = { mass: 0.9, damping: 15, stiffness: 90 };
const SCALE_SPRING_MAIN = { mass: 2, damping: 25, stiffness: 100 };
const SCALE_SPRING_BG = { mass: 1, damping: 20, stiffness: 50 };

const SCALE_ASPECT_MAIN = 97;
const SCALE_ASPECT_BG = 75;




const OVERFLOW_PENALTY_MULTIPLIER = 1000;
const CJK_BREAK_PENALTY_RATIO = 0.15;
const NORMAL_BREAK_PENALTY_RATIO = 0.5;
const SPACE_BREAK_REWARD_RATIO = 0.4;
const PUNCTUATION_BREAK_REWARD_RATIO = 0.6;
const PUNCTUATION_REGEX = /[,.;:!?，。；：！？、）】》」』'”)\]}>~…]$/;

function calcBalancedBreaks(children, containerWidth, fullText, segmenter) {
  const n = children.length;
  if (n === 0 || containerWidth <= 0) return [];

  
  const cjkBoundaries = new Set();
  let offset = 0;
  for (const { segment, isWordLike } of segmenter.segment(fullText)) {
    if (offset > 0 && isWordLike) {
      if ([...segment].some(ch => isCJK(ch))) {
        cjkBoundaries.add(offset);
      }
    }
    offset += segment.length;
  }

  const charOffsets = new Int32Array(n + 1);
  const prefixWidth = new Float64Array(n + 1);
  for (let i = 0; i < n; i++) {
    charOffsets[i + 1] = charOffsets[i] + children[i].text.length;
    prefixWidth[i + 1] = prefixWidth[i] + children[i].width;
  }

  if (prefixWidth[n] <= containerWidth) return [];

  const dp = new Float64Array(n + 1).fill(Number.POSITIVE_INFINITY);
  const nextBreak = new Int32Array(n + 1).fill(-1);
  dp[n] = 0;

  const PENALTY_CJK = (containerWidth * CJK_BREAK_PENALTY_RATIO) ** 2;
  const PENALTY_NORMAL = (containerWidth * NORMAL_BREAK_PENALTY_RATIO) ** 2;

  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j <= n; j++) {
      const w = prefixWidth[j] - prefixWidth[i];
      let lineCost = 0;
      if (w > containerWidth) {
        if (j === i + 1) {
          lineCost = (w - containerWidth) ** 2 * OVERFLOW_PENALTY_MULTIPLIER;
        } else {
          continue;
        }
      } else {
        lineCost = (containerWidth - w) ** 2;
      }
      let breakPenalty = 0;
      if (j < n) {
        const prevChild = children[j - 1];
        if (PUNCTUATION_REGEX.test(prevChild.text)) {
          breakPenalty = -((containerWidth * PUNCTUATION_BREAK_REWARD_RATIO) ** 2);
        } else if (prevChild.isSpace) {
          breakPenalty = -((containerWidth * SPACE_BREAK_REWARD_RATIO) ** 2);
        } else if (cjkBoundaries.has(charOffsets[j])) {
          breakPenalty = PENALTY_CJK;
        } else {
          breakPenalty = PENALTY_NORMAL;
        }
      }
      const totalCost = lineCost + breakPenalty + dp[j];
      if (totalCost < dp[i]) {
        dp[i] = totalCost;
        nextBreak[i] = j;
      }
    }
  }

  const breaks = [];
  let curr = 0;
  while (curr < n) {
    curr = nextBreak[curr];
    if (curr > 0 && curr < n) breaks.push(curr);
  }
  return breaks;
}

class LineBalancer {
  constructor(mainElement) {
    this.mainElement = mainElement;
    this.isBalancing = false;
    this.lastBalancedContainerWidth = -1;
  }

  
  getContainerWidth(mainStyle) {
    if (!this.mainElement) return 0;
    const cs = mainStyle ?? getComputedStyle(this.mainElement);
    const paddingLeft = Number.parseFloat(cs.paddingLeft) || 0;
    const paddingRight = Number.parseFloat(cs.paddingRight) || 0;
    return this.mainElement.clientWidth - paddingLeft - paddingRight;
  }

  balanceLineBreaks(hasSplittedWords, wordSegmenter) {
    if (this.isBalancing || !this.mainElement) return;
    const containerWidth = this.getContainerWidth();
    if (containerWidth <= 0) return;
    if (!hasSplittedWords) return;
    this.executeLineBalance(containerWidth, wordSegmenter);
  }

  reset() {
    this.lastBalancedContainerWidth = -1;
  }

  executeLineBalance(containerWidth, wordSegmenter) {
    const existingBrs = this.mainElement.querySelectorAll("br");
    if (containerWidth === this.lastBalancedContainerWidth && existingBrs.length > 0) return;

    
    this.mainElement.querySelectorAll("br").forEach(br => br.remove());

    
    const prevWhiteSpace = this.mainElement.style.whiteSpace;
    this.mainElement.style.whiteSpace = "nowrap";

    
    const parentElement = this.mainElement.parentElement;
    let prevTransform = "";
    let transformChanged = false;
    if (parentElement) {
      prevTransform = parentElement.style.transform;
      if (prevTransform && prevTransform !== "none") {
        parentElement.style.transform = "none";
        transformChanged = true;
      }
    }

    try {
      const infoToNode = [];
      const childNodes = Array.from(this.mainElement.childNodes);
      const childInfos = [];
      const range = document.createRange();

      for (const node of childNodes) {
        if (node.nodeType === Node.TEXT_NODE) {
          const text = node.textContent ?? "";
          if (text.length === 0) continue;
          range.selectNodeContents(node);
          childInfos.push({
            width: range.getBoundingClientRect().width,
            text: text,
            isSpace: text.trim().length === 0
          });
          infoToNode.push(node);
        } else if (node.nodeType === Node.ELEMENT_NODE) {
          const el = node;
          const rect = el.getBoundingClientRect();
          const elStyle = getComputedStyle(el);
          const marginLeft = Number.parseFloat(elStyle.marginLeft) || 0;
          const marginRight = Number.parseFloat(elStyle.marginRight) || 0;
          childInfos.push({
            width: clampPositive(rect.width + marginLeft + marginRight),
            text: el.textContent ?? "",
            isSpace: false
          });
          infoToNode.push(node);
        }
      }
      const fullText = childInfos.map(c => c.text).join("");
      const layoutWidth = childInfos.reduce((sum, c) => sum + c.width, 0);
      const safeContainerWidth = Math.max(1, containerWidth);

      if (layoutWidth > safeContainerWidth && childInfos.length > 0) {
        const breaks = calcBalancedBreaks(childInfos, safeContainerWidth, fullText, wordSegmenter);
        if (breaks.length > 0) {
          this.isBalancing = true;
          for (let i = breaks.length - 1; i >= 0; i--) {
            let breakIndex = breaks[i];
            if (breakIndex >= 0 && breakIndex < infoToNode.length) {
              
              
              
              while (breakIndex < infoToNode.length) {
                const node = infoToNode[breakIndex];
                const isSpaceText = node.nodeType === Node.TEXT_NODE &&
                  (node.textContent ?? "").trim().length === 0;
                if (!isSpaceText) break;
                breakIndex++;
              }
              if (breakIndex < infoToNode.length) {
                this.mainElement.insertBefore(document.createElement("br"), infoToNode[breakIndex]);
              }
            }
          }
          this.isBalancing = false;
        }
      }
      this.lastBalancedContainerWidth = containerWidth;
    } finally {
      this.mainElement.style.whiteSpace = prevWhiteSpace;
      if (transformChanged && parentElement) {
        parentElement.style.transform = prevTransform;
      }
    }
  }
}



const ANIMATION_FRAME_QUANTITY = 32;
const EMP_EASING_MID = 0.5;
const bezIn = makeBezier(0.2, 0.4, 0.58, 1.0);
const bezOut = makeBezier(0.3, 0.0, 0.58, 1.0);
const norNum = (min, max) => (x) => clamp01((x - min) / (max - min));
const beginNum = norNum(0, EMP_EASING_MID);
const endNum = norNum(EMP_EASING_MID, 1);
const makeEmpEasing = (mid) => (x) =>
  x < mid ? bezIn(beginNum(x)) : 1 - bezOut(endNum(x));
const empEasing = makeEmpEasing(EMP_EASING_MID);





function shouldEmphasize(word) {
  if (isCJK(word.word)) return word.endTime - word.startTime >= 1000;
  return (
    word.endTime - word.startTime >= 1000 &&
    word.word.trim().length <= 7 &&
    word.word.trim().length > 1
  );
}


function createFloatAnimation(wordEl, options) {
  const { word, lineStartTime, isBG } = options;
  const delay = word.startTime - lineStartTime;
  const duration = Math.max(1000, word.endTime - word.startTime);
  let up = 0.05;
  if (isBG) up *= 2;
  const a = wordEl.animate(
    [{ transform: "translateY(0px)" }, { transform: `translateY(${-up}em)` }],
    {
      duration: Number.isFinite(duration) ? duration : 0,
      delay: Number.isFinite(delay) ? delay : 0,
      id: "float-word",
      composite: "add",
      fill: "both",
      easing: "ease-out",
    },
  );
  a.pause();
  return a;
}


function calculateEmphasizeParams(options) {
  const { duration, delay, rubyCharCount, characterElements, isLastWord } = options;
  const de = clampPositive(delay);
  let du = Math.max(1000, duration);
  const anchorCharCount = rubyCharCount > 0 ? rubyCharCount : Math.max(1, characterElements.length);

  let amount = du / 2000;
  amount = amount > 1 ? Math.sqrt(amount) : amount ** 3;
  let blur = du / 3000;
  blur = blur > 1 ? Math.sqrt(blur) : blur ** 3;
  amount *= 0.6;
  blur *= 0.5;
  
  if (isLastWord) {
    amount *= 1.6;
    blur *= 1.5;
    du *= 1.2;
  }
  amount = Math.min(1.2, amount);
  blur = Math.min(0.8, blur);
  const animateDu = Number.isFinite(du) ? du : 0;
  return { amount, blur, du, de, anchorCharCount, animateDu };
}

function generateGlowKeyframes(charIndex, totalChars, amount, blur) {
  return new Array(ANIMATION_FRAME_QUANTITY).fill(0).map((_, j) => {
    const x = (j + 1) / ANIMATION_FRAME_QUANTITY;
    const transX = empEasing(x);
    const glowLevel = transX * blur;
    const scaleVal = 1 + transX * 0.1 * amount;
    
    const offsetX = -transX * 0.03 * amount * (totalChars / 2 - charIndex);
    const offsetY = -transX * 0.025 * amount;
    return {
      offset: x,
      transform: `scale(${scaleVal.toFixed(4)}) translate(${offsetX.toFixed(4)}em, ${offsetY.toFixed(4)}em)`,
      textShadow: `0 0 ${Math.min(0.3, blur * 0.3).toFixed(3)}em rgba(var(--active-rgb, 255, 255, 255), ${glowLevel.toFixed(3)})`
    };
  });
}

function generateFloatKeyframes(isBG) {
  return new Array(ANIMATION_FRAME_QUANTITY).fill(0).map((_, j) => {
    const x = (j + 1) / ANIMATION_FRAME_QUANTITY;
    let y = Math.sin(x * Math.PI);
    if (isBG) y *= 2;
    return {
      offset: x,
      transform: `translateY(${(-y * 0.05).toFixed(4)}em)`
    };
  });
}


function createEmphasizeAnimation(options) {
  const params = calculateEmphasizeParams(options);
  const totalChars = options.characterElements.length;
  const result = [];

  options.characterElements.forEach((el, i) => {
    const wordDe = params.de + (params.du / 2.5 / params.anchorCharCount) * i;

    
    const frames = generateGlowKeyframes(i, totalChars, params.amount, params.blur);
    const glow = el.animate(frames, {
      duration: params.animateDu,
      delay: Number.isFinite(wordDe) ? wordDe : 0,
      id: `emphasize-word-${i}`,
      iterations: 1,
      composite: "replace",
      fill: "both"
    });
    glow.onfinish = () => { glow.pause(); };
    glow.pause();
    result.push(glow);

    
    const floatFrames = generateFloatKeyframes(options.isBG);
    const float = el.animate(floatFrames, {
      duration: params.animateDu * 1.4,
      delay: Number.isFinite(wordDe) ? wordDe - 400 : 0,
      id: "emphasize-word-float",
      iterations: 1,
      composite: "add",
      fill: "both"
    });
    float.onfinish = () => { float.pause(); };
    float.pause();
    result.push(float);
  });

  return result;
}





const WORD_FADE_WIDTH = 0.5; 

function generateFadeGradient(width) {
  const bright = "rgba(0,0,0,var(--bright-mask-alpha, 1))";
  const dark = "rgba(0,0,0,var(--dark-mask-alpha, 1))";
  const totalAspect = 2 + width;
  const halfFadePercent = (width / totalAspect) * 50;
  const leftPercent = 50 - halfFadePercent;
  const rightPercent = 50 + halfFadePercent;
  return [
    `linear-gradient(to right, ${bright} ${leftPercent}%, ${dark} ${rightPercent}%)`,
    totalAspect
  ];
}


class WebMaskAnimator {
  constructor(words, context) {
    this.words = words;
    this.context = context;
    this.animations = [];
    this.totalFadeDuration = Math.max(1, context.lineEndTime - context.lineStartTime);
  }

  apply() {
    this.buildAnimations();
  }

  setCurrentTime(timeRelative, isPlaying) {
    const t = Math.min(this.totalFadeDuration, Math.max(0, timeRelative));
    for (const a of this.animations) {
      a.currentTime = t;
      a.playbackRate = 1;
      const endTime = this.getAnimationEndTime(a);
      if (isPlaying && t < endTime) a.play();
      else a.pause();
    }
  }

  pause() {
    for (const a of this.animations) a.pause();
  }

  resume() {
    for (const a of this.animations) {
      const endTime = this.getAnimationEndTime(a);
      const currentTime = Number(a.currentTime ?? 0);
      if (a.playState !== "finished" && currentTime < endTime) a.play();
    }
  }

  buildAnimations() {
    for (const [i, word] of this.words.entries()) {
      const wordEl = word.mainElement;
      if (!wordEl) continue;
      const fadeWidth = word.height * this.context.wordFadeWidth;
      this.updateWordMaskStyles(wordEl, word, fadeWidth);
      const frames = this.generateWordKeyframes(word, i, fadeWidth);
      try {
        const ani = wordEl.animate(frames, {
          duration: Math.max(this.totalFadeDuration, 1),
          id: `fade-word-${i}`,
          fill: "both"
        });
        ani.pause();
        this.animations.push(ani);
      } catch (err) {
        console.warn("应用渐变动画发生错误", err);
      }
    }
  }

  updateWordMaskStyles(wordEl, word, fadeWidth) {
    
    
    const denom = Math.max(1, word.width + word.padding * 2);
    const [maskImage, totalAspect] = generateFadeGradient(
      fadeWidth / denom
    );
    wordEl.style.webkitMaskImage = maskImage;
    wordEl.style.maskImage = maskImage;
    wordEl.style.webkitMaskRepeat = "no-repeat";
    wordEl.style.maskRepeat = "no-repeat";
    wordEl.style.webkitMaskSize = `${totalAspect * 100}% 100%`;
    wordEl.style.maskSize = `${totalAspect * 100}% 100%`;
  }

  generateWordKeyframes(targetWord, targetIndex, fadeWidth) {
    const words = this.words;
    const widthBeforeSelf =
      words.slice(0, targetIndex).reduce((a, b) => a + b.width, 0) +
      (words[0] ? fadeWidth : 0);
    const minOffset = -(targetWord.width + targetWord.padding * 2 + fadeWidth);
    let curPos = -widthBeforeSelf - targetWord.width - targetWord.padding - fadeWidth;
    let timeOffset = 0;
    let lastPos = curPos;
    let lastTime = 0;
    let lastTimeStamp = 0;
    const frames = [];
    const clampOffset = (x) => Math.min(Math.max(x, minOffset), 0);

    const pushFrame = () => {
      const moveOffset = curPos - lastPos;
      const time = Math.min(1, Math.max(0, timeOffset));
      const duration = time - lastTime;
      const msPerPixel = moveOffset !== 0 ? Math.abs(duration / moveOffset) : 0;
      
      if (curPos > minOffset && lastPos < minOffset) {
        const staticTime = Math.abs(lastPos - minOffset) * msPerPixel;
        frames.push({
          offset: lastTime + staticTime,
          maskPosition: `${clampOffset(lastPos)}px 0`,
          webkitMaskPosition: `${clampOffset(lastPos)}px 0`
        });
      }
      
      if (curPos > 0 && lastPos < 0) {
        const staticTime = Math.abs(lastPos) * msPerPixel;
        frames.push({
          offset: lastTime + staticTime,
          maskPosition: `${clampOffset(curPos)}px 0`,
          webkitMaskPosition: `${clampOffset(curPos)}px 0`
        });
      }
      frames.push({
        offset: time,
        maskPosition: `${clampOffset(curPos)}px 0`,
        webkitMaskPosition: `${clampOffset(curPos)}px 0`
      });
      lastPos = curPos;
      lastTime = time;
    };

    pushFrame();

    for (const [j, otherWord] of words.entries()) {
      
      {
        const curTimeStamp = otherWord.startTime - this.context.lineStartTime;
        const staticDuration = Math.max(0, curTimeStamp - lastTimeStamp);
        timeOffset += staticDuration / this.totalFadeDuration;
        if (staticDuration > 0) pushFrame();
        lastTimeStamp = Math.max(lastTimeStamp, curTimeStamp);
      }
      
      const rubySegments = otherWord.ruby?.filter(r => r?.word?.trim()) ?? [];
      if (rubySegments.length > 0) {
        this.advanceRubyWordTimeline(rubySegments, otherWord, fadeWidth, j, {
          getCursor: () => ({ curPos, timeOffset, lastTimeStamp }),
          setCursor: (c) => { curPos = c.curPos; timeOffset = c.timeOffset; lastTimeStamp = c.lastTimeStamp; },
          pushFrame
        });
      } else {
        const fadeDuration = Math.max(0, otherWord.endTime - otherWord.startTime);
        let movePx = otherWord.width;
        if (j === 0) movePx += fadeWidth * 1.5;
        if (j === words.length - 1) movePx += fadeWidth * 0.5;
        timeOffset += fadeDuration / this.totalFadeDuration;
        curPos += movePx;
        if (fadeDuration > 0) pushFrame();
        lastTimeStamp += fadeDuration;
      }
    }
    return frames;
  }

  


  advanceRubyWordTimeline(rubySegments, otherWord, fadeWidth, wordIndex, cursorApi) {
    const words = this.words;
    const rubyCharCount = rubySegments.reduce((sum, r) => sum + r.word.length, 0);
    const widthPerChar = otherWord.width / rubyCharCount;
    let charIndex = 0;
    let { curPos, timeOffset, lastTimeStamp } = cursorApi.getCursor();
    const pushFrame = cursorApi.pushFrame;

    for (const ruby of rubySegments) {
      const rubyStart = Math.max(ruby.startTime, otherWord.startTime);
      const rubyEnd = Math.min(Math.max(ruby.endTime, rubyStart), otherWord.endTime);
      const rubyStartStamp = rubyStart - this.context.lineStartTime;
      const rubyStaticDuration = rubyStartStamp - lastTimeStamp;
      if (rubyStaticDuration > 0) {
        timeOffset += rubyStaticDuration / this.totalFadeDuration;
        pushFrame();
      }
      lastTimeStamp = rubyStartStamp;

      const rubyDuration = Math.max(0, rubyEnd - rubyStart);
      const perCharDuration = rubyDuration / ruby.word.length;
      for (let i = 0; i < ruby.word.length; i++) {
        let movePx = widthPerChar;
        if (wordIndex === 0 && charIndex === 0) movePx += fadeWidth * 1.5;
        if (wordIndex === words.length - 1 && charIndex === rubyCharCount - 1) movePx += fadeWidth * 0.5;
        timeOffset += perCharDuration / this.totalFadeDuration;
        curPos += movePx;
        if (perCharDuration > 0) pushFrame();
        lastTimeStamp += perCharDuration;
        charIndex++;
      }
    }

    const wordEndStamp = Math.max(otherWord.endTime - this.context.lineStartTime, lastTimeStamp);
    const wordTailDuration = wordEndStamp - lastTimeStamp;
    if (wordTailDuration > 0) {
      timeOffset += wordTailDuration / this.totalFadeDuration;
      pushFrame();
    }
    lastTimeStamp = wordEndStamp;
    cursorApi.setCursor({ curPos, timeOffset, lastTimeStamp });
  }

  getAnimationEndTime(animation) {
    const timing = animation.effect?.getComputedTiming();
    return Number(timing?.delay ?? 0) + Number(timing?.duration ?? 0);
  }

  dispose() {
    for (const a of this.animations) a.cancel();
    this.animations.length = 0;
    for (const word of this.words) {
      const wordEl = word.mainElement;
      if (wordEl) {
        wordEl.style.removeProperty("mask");
        wordEl.style.removeProperty("-webkit-mask");
      }
    }
  }
}







const BRIGHTNESS_SETTLE_MS = 500;

const BRIGHTNESS_WINDOW_LINES = 2;

class LineBrightness {
  constructor(main, enabled = true) {
    this.main = main;
    this.enabled = enabled;
    this.dim = undefined;          
    this.transitionRestore = undefined; 
    this.inWindow = true;          
    this.highlightExitedAt = 0;    
    this.dimAnimation = undefined; 
    this.mainAnimation = undefined;
    this.isDisposed = false;
  }

  get disposed() { return this.isDisposed; }
  get isReady() { return !this.isDisposed && this.dim !== undefined; }

  
  setInWindow(inWindow) {
    if (this.isDisposed) return;
    if (this.inWindow === inWindow) {
      if (!inWindow) this.sync();
      return;
    }
    this.inWindow = inWindow;
    this.sync();
  }

  
  markHighlightExited() {
    if (this.isDisposed) return;
    this.cancelActivationAnimation();
    this.highlightExitedAt = performance.now();
  }

  
  playActivationTransition() {
    if (this.isDisposed || !this.dim) return;
    this.cancelActivationAnimation();
    const dimAnim = this.dim.animate(
      [{ opacity: 0.2 }, { opacity: 0 }],
      { duration: 300, easing: "ease-out" }
    );
    this.dimAnimation = dimAnim;
    dimAnim.onfinish = () => { if (this.dimAnimation === dimAnim) this.dimAnimation = undefined; };
    const mainAnim = this.main.animate(
      [{ opacity: 0 }, { opacity: 1 }],
      { duration: 300, easing: "ease-out" }
    );
    this.mainAnimation = mainAnim;
    mainAnim.onfinish = () => { if (this.mainAnimation === mainAnim) this.mainAnimation = undefined; };
  }

  cancelActivationAnimation() {
    if (this.dimAnimation) { this.dimAnimation.cancel(); this.dimAnimation = undefined; }
    if (this.mainAnimation) { this.mainAnimation.cancel(); this.mainAnimation = undefined; }
  }

  
  sync(forceRebuild = false) {
    if (this.isDisposed) return;
    if (!this.enabled) {
      if (this.isReady) this.deactivate();
      return;
    }
    if (this.inWindow) {
      if ((!this.isReady || forceRebuild) && this.main.isConnected) {
        this.rebuild();
      }
      return;
    }
    
    if (this.isReady && performance.now() - this.highlightExitedAt >= BRIGHTNESS_SETTLE_MS) {
      this.deactivate();
    }
  }

  


  captureGeometry() {
    if (this.isDisposed) return;
    if (!this.dim) return;
    if (this.main.clientWidth <= 0) return;
    const geometry = this.measureGeometry();
    if (geometry) Object.assign(this.dim.style, geometry);
  }

  
  rebuild() {
    if (!this.enabled || this.isDisposed) return;
    const parent = this.main.parentElement;
    
    
    
    if (parent && this.main.clientWidth <= 0) return;
    
    
    const geometry = this.measureGeometry();
    if (!parent || !geometry) return;

    this.clearCopy();

    const dim = this.main.cloneNode(true);
    if (!(dim instanceof HTMLElement)) return;

    dim.classList.remove("bright");
    dim.classList.add("dim");
    dim.setAttribute("aria-hidden", "true");
    if ("inert" in dim) dim.inert = true;
    
    dim.style.removeProperty("transition");
    Object.assign(dim.style, geometry);

    
    dim.style.removeProperty("mask");
    dim.style.removeProperty("-webkit-mask");
    for (const element of dim.querySelectorAll("*")) {
      if (!(element instanceof HTMLElement)) continue;
      element.style.removeProperty("mask");
      element.style.removeProperty("-webkit-mask");
    }
    
    
    
    
    for (const selector of [".lyric-sub.trans", ".lyric-sub.roman", ".roman-word", ".ruby-word"]) {
      const originals = this.main.querySelectorAll(selector);
      const copies = dim.querySelectorAll(selector);
      for (let i = 0; i < originals.length && i < copies.length; i++) {
        const src = originals[i];
        if (src.__subType !== undefined) {
          copies[i].__subType = src.__subType;
          copies[i].__subNatural = src.__subNatural;
          copies[i].__subBaseOpacity = src.__subBaseOpacity;
        }
      }
    }

    parent.appendChild(dim);

    
    this.setMainBright(true);
    this.dim = dim;
  }

  
  deactivate() {
    if (this.isDisposed) return;
    this.clearCopy();
    this.setMainBright(false);
  }

  
  dispose() {
    if (this.isDisposed) return;
    this.isDisposed = true;
    this.releaseTransitionSuppression();
    this.clearCopy();
    this.main.classList.remove("bright");
    this.main.style.transition = "";
  }

  







  measureGeometry() {
    const parent = this.main.parentElement;
    if (!parent) return undefined;
    
    
    if (this.main.clientWidth <= 0) return undefined;
    
    
    if (this.main.offsetParent !== parent) return undefined;
    const left = this.main.offsetLeft;
    const top = this.main.offsetTop;
    
    const right = parent.clientWidth - left - this.main.offsetWidth;
    return {
      top: `${top}px`,
      left: `${left}px`,
      right: `${right}px`
    };
  }

  
  setMainBright(enabled) {
    if (this.isDisposed) return;
    if (this.main.classList.contains("bright") === enabled) return;

    this.releaseTransitionSuppression();
    this.main.classList.toggle("bright", enabled);

    if (!this.main.isConnected) return;

    this.main.style.transition = "none";
    this.transitionRestore = requestAnimationFrame(() => {
      this.transitionRestore = undefined;
      if (this.isDisposed || !this.main.isConnected) {
        this.main.style.transition = "";
        return;
      }
      this.releaseTransitionSuppression();
    });
  }

  releaseTransitionSuppression() {
    if (this.transitionRestore !== undefined) {
      cancelAnimationFrame(this.transitionRestore);
      this.transitionRestore = undefined;
    }
    this.main.style.transition = "";
  }

  clearCopy() {
    this.cancelActivationAnimation();
    this.dim?.remove();
    this.dim = undefined;
  }
}





const wordSegmenter = (typeof Intl !== "undefined" && Intl.Segmenter)
  ? new Intl.Segmenter(undefined, { granularity: "word" })
  : null;
const graphemeSegmenter = (typeof Intl !== "undefined" && Intl.Segmenter)
  ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
  : null;
const supportMaskImage = typeof CSS !== "undefined" && CSS.supports && CSS.supports("mask-image", "none");

class LyricLineEl {
  constructor(lyricPlayer, lyricLine) {
    this.lyricPlayer = lyricPlayer;
    this.lyricLine = lyricLine;
    this.element = document.createElement("div");
    this.element.setAttribute("class", "lyric-line");
    if (lyricLine.isBG) this.element.classList.add("bg");
    if (lyricLine.isDuet) this.element.classList.add("duet");

    
    this.lineTransforms = {
      scale: new Spring(100, lyricLine.isBG ? SCALE_SPRING_BG : SCALE_SPRING_MAIN)
    };

    this.isEnabled = false;
    this.built = false;
    this.splittedWords = [];
    this.maskAnimator = undefined;
    this.isUiDirty = true;
    this.lastScaleNum = -1;
    this.renderMode = 0;
    this.maskSignature = "";
    this.lastLineSize = undefined;
    this.balancer = wordSegmenter ? new LineBalancer(null) : undefined;

    this.element.appendChild(document.createElement("div")); 
    this.element.appendChild(document.createElement("div")); 
    this.element.appendChild(document.createElement("div")); 
    this.mainEl = this.element.children[0];
    this.transEl = this.element.children[1];
    this.romanEl = this.element.children[2];
    this.mainEl.className = "lyric-main";
    this.transEl.className = "lyric-sub trans";
    this.romanEl.className = "lyric-sub roman";
    
    this.transInnerEl = document.createElement("div");
    this.romanInnerEl = document.createElement("div");
    this.transEl.appendChild(this.transInnerEl);
    this.romanEl.appendChild(this.romanInnerEl);
    
    if (lyricPlayer.swapSubLines) {
      this.element.insertBefore(this.romanEl, this.transEl);
    }
    
    const zeroDurLine = !!(this.lyricLine && this.lyricLine.words && this.lyricLine.words.length && this.lyricLine.words.every(w => w.endTime <= w.startTime));
    this.brightness = new LineBrightness(this.mainEl, !lyricPlayer.isNonDynamic && !zeroDurLine && !this.lyricLine.isMeta);
    if (this.balancer) this.balancer.mainElement = this.mainEl;
  }

  
  applySubLinesOrder(swap) {
    if (swap) {
      if (this.romanEl.nextElementSibling !== this.transEl) {
        this.element.insertBefore(this.romanEl, this.transEl);
      }
    } else {
      if (this.transEl.nextElementSibling !== this.romanEl) {
        this.element.insertBefore(this.transEl, this.romanEl);
      }
    }
  }

  get totalDuration() {
    return this.lyricLine.endTime - this.lyricLine.startTime;
  }

  getElement() {
    return this.element;
  }

  getLine() {
    return this.lyricLine;
  }

  
  enable(maskAnimationTime, shouldPlay) {
    this.isEnabled = true;
    this.element.classList.add("active");
    if (maskAnimationTime === undefined) {
      maskAnimationTime = this.lyricPlayer.getCurrentTime();
    }
    if (shouldPlay === undefined) {
      shouldPlay = this.lyricPlayer.getIsPlaying();
    }
    const relativeTime = clampPositive(maskAnimationTime - this.lyricLine.startTime);
    for (const word of this.splittedWords) {
      for (const a of word.elementAnimations) {
        a.currentTime = relativeTime;
        a.playbackRate = 1;
        const timing = a.effect?.getComputedTiming();
        const endTime = Number(timing?.delay ?? 0) + Number(timing?.duration ?? 0);
        if (shouldPlay && relativeTime < endTime) a.play();
        else a.pause();
      }
    }
    this.maskAnimator?.setCurrentTime(relativeTime, shouldPlay);
  }

  
  disable() {
    this.isEnabled = false;
    this.element.classList.remove("active");
    this.setRenderMode(false);
    for (const word of this.splittedWords) {
      for (const a of word.elementAnimations) {
        if (a.id === "float-word" || a.id === "emphasize-word-float") {
          a.playbackRate = -1;
          a.play();
        }
      }
    }
    this.maskAnimator?.pause();
  }

  resume() {
    if (!this.isEnabled) return;
    for (const word of this.splittedWords) {
      for (const a of word.elementAnimations) {
        const timing = a.effect?.getComputedTiming();
        const endTime = Number(timing?.delay ?? 0) + Number(timing?.duration ?? 0);
        const ct = Number(a.currentTime ?? 0);
        if (a.playState !== "finished" && ct < endTime) a.play();
      }
    }
    this.maskAnimator?.resume();
  }

  pause() {
    if (!this.isEnabled) return;
    for (const word of this.splittedWords) {
      for (const a of word.elementAnimations) a.pause();
    }
    this.maskAnimator?.pause();
  }

  setRenderMode(isGradient) {
    const next = isGradient ? 1 : 0;
    if (this.renderMode === next) return;
    
    if (this.renderMode === 1) {
      this.brightness.markHighlightExited();
    }
    this.renderMode = next;
    this.element.classList.toggle("gradient-mask", isGradient);
  }

  
  show() {
    if (!this.built) {
      this.rebuildElement();
      this.built = true;
      this.syncMaskAfterRebuild();
    } else if (!this.maskAnimator) {
      
      this.updateMaskImageSync();
    }
    this.brightness.sync();
  }

  
  hide() {
    this.brightness.deactivate();
  }

  
  syncMaskAfterRebuild() {
    if (this.element.isConnected) this.updateMaskImageSync();
  }

  rebuildElement() {
    this.disposeElements();
    if (this.lyricPlayer.isNonDynamic && !this.lyricLine.isMeta) {
      
      this.mainEl.textContent = this.lyricLine.words.map(w => w.word).join("");
      this.transInnerEl.textContent = this.lyricLine.translatedLyric;
      this.romanInnerEl.textContent = this.lyricLine.romanLyric;
      if (!this.lyricLine.translatedLyric) this.transEl.style.display = "none";
      if (!this.lyricLine.romanLyric) this.romanEl.style.display = "none";
      this.syncMaskAfterRebuild();
      return;
    }
    const chunkedWords = chunkAndSplitLyricWords(this.lyricLine.words);
    const hasRubyLine = this.lyricLine.words.some(w => (w.ruby?.length ?? 0) > 0);
    const hasRomanLine = this.lyricLine.words.some(w => (w.romanWord?.trim().length ?? 0) > 0);
    this.mainEl.innerHTML = "";
    
    this.creatorImgDone = false;
    for (const chunk of chunkedWords) {
      this.buildWord(chunk, hasRubyLine, hasRomanLine);
    }
    this.transInnerEl.textContent = this.lyricLine.translatedLyric;
    this.romanInnerEl.textContent = this.lyricLine.romanLyric;
    if (!this.lyricLine.translatedLyric) this.transEl.style.display = "none";
    if (!this.lyricLine.romanLyric) this.romanEl.style.display = "none";
    else this.romanEl.style.display = "";
    this.syncMaskAfterRebuild();
  }

  getRubyCharCount(word) {
    return (word.ruby ?? []).reduce((total, ruby) => total + ruby.word.length, 0);
  }

  getRubySegments(word) {
    return (word.ruby ?? []).filter(ruby => (ruby?.word?.trim().length ?? 0) > 0);
  }

  
  createWord(word, shouldEmphasize, hasRubyLine, hasRomanLine) {
    const mainWordEl = document.createElement("span");
    const subElements = [];
    const romanWord = word.romanWord?.trim() ?? "";
    const wordContainer = hasRubyLine ? document.createElement("span") : mainWordEl;
    const wordTextContainer = hasRubyLine ? document.createElement("span") : wordContainer;

    if (hasRubyLine) {
      const rubyWordEl = document.createElement("span");
      const rubySegments = this.getRubySegments(word);
      for (const ruby of rubySegments) {
        const rubyPartEl = document.createElement("span");
        rubyPartEl.textContent = ruby.word;
        rubyWordEl.appendChild(rubyPartEl);
      }
      rubyWordEl.classList.add("ruby-word");
      mainWordEl.classList.add("word-with-ruby");
      wordContainer.classList.add("word-body");
      wordTextContainer.classList.add("ruby-base-word");
      wordContainer.appendChild(wordTextContainer);
      mainWordEl.appendChild(rubyWordEl);
      mainWordEl.appendChild(wordContainer);
    }

    const displayWord = word.word;

    if (shouldEmphasize) {
      mainWordEl.classList.add("emphasize");
      const trimmedWord = displayWord.trim();
      if (graphemeSegmenter) {
        for (const { segment } of graphemeSegmenter.segment(trimmedWord)) {
          const charEl = document.createElement("span");
          charEl.textContent = segment;
          subElements.push(charEl);
          wordTextContainer.appendChild(charEl);
        }
      } else {
        for (const segment of Array.from(trimmedWord)) {
          const charEl = document.createElement("span");
          charEl.textContent = segment;
          subElements.push(charEl);
          wordTextContainer.appendChild(charEl);
        }
      }
    } else {
      if (hasRomanLine) {
        const wordEl = document.createElement("span");
        wordEl.textContent = displayWord.trim();
        wordTextContainer.appendChild(wordEl);
      } else if (romanWord.length === 0) {
        wordTextContainer.textContent = displayWord.trim();
      }
    }

    if (hasRomanLine) {
      const romanWordEl = document.createElement("span");
      const romanWordInnerEl = document.createElement("span");
      romanWordInnerEl.textContent = romanWord.length > 0 ? romanWord : "\u00A0";
      romanWordInnerEl.className = "roman-word-inner";
      romanWordEl.appendChild(romanWordInnerEl);
      romanWordEl.classList.add("roman-word");
      wordContainer.appendChild(romanWordEl);
    }

    const realWord = {
      ...word,
      mainElement: mainWordEl,
      subElements: subElements,
      elementAnimations: [
        createFloatAnimation(mainWordEl, {
          word: word,
          lineStartTime: this.lyricLine.startTime,
          isBG: this.lyricLine.isBG
        })
      ],
      width: 0,
      height: 0,
      padding: 0,
      shouldEmphasize: shouldEmphasize
    };
    return realWord;
  }

  buildWord(input, hasRubyLine, hasRomanLine) {
    const chunk = Array.isArray(input) ? input : [input];
    if (chunk.length === 0) return;

    const isPureSpace = chunk.every(w => !w.word.trim());
    if (isPureSpace) {
      const textContent = chunk.map(w => w.word).join("");
      this.mainEl.appendChild(document.createTextNode(textContent));
      return;
    }

    const merged = chunk.reduce((a, b) => {
      a.endTime = Math.max(a.endTime, b.endTime);
      a.startTime = Math.min(a.startTime, b.startTime);
      a.word += b.word;
      return a;
    }, {
      word: "", romanWord: "",
      startTime: Number.POSITIVE_INFINITY,
      endTime: Number.NEGATIVE_INFINITY
    });

    let emp = chunk.some(w => shouldEmphasize(w));
    if (!isCJK(merged.word)) {
      emp = emp || shouldEmphasize(merged);
    }

    const wrapperWordEl = document.createElement("span");
    wrapperWordEl.classList.add("emphasize-wrapper");
    const creatorWord = chunk.find(w => w.url);
    if (creatorWord) {
      wrapperWordEl.classList.add("lyric-creator");
    }
    const characterElements = [];

    for (const word of chunk) {
      if (!word.word.trim()) {
        wrapperWordEl.appendChild(document.createTextNode(word.word));
        continue;
      }
      const realWord = this.createWord(word, emp, hasRubyLine, hasRomanLine);
      if (emp) {
        characterElements.push(...realWord.subElements);
      }
      this.splittedWords.push(realWord);
      wrapperWordEl.appendChild(realWord.mainElement);
    }

    
    if (emp && this.splittedWords.length > 0) {
      const lastWordOfChunk = this.splittedWords[this.splittedWords.length - 1];
      const rubyCharCount = chunk.reduce((total, word) => total + this.getRubyCharCount(word), 0);
      const lineWords = this.lyricLine.words;
      const isLastWord =
        lineWords.length > 0 &&
        merged.word.includes(lineWords[lineWords.length - 1].word);

      lastWordOfChunk.elementAnimations.push(
        ...createEmphasizeAnimation({
          word: merged,
          characterElements: characterElements,
          duration: merged.endTime - merged.startTime,
          delay: merged.startTime - this.lyricLine.startTime,
          rubyCharCount: rubyCharCount,
          isBG: this.lyricLine.isBG,
          isLastWord: isLastWord
        })
      );
    }

    this.mainEl.appendChild(wrapperWordEl);
  }

  onLineSizeChange(size) {
    
    const w = size?.[0];
    const h = size?.[1];
    if (
      this.maskAnimator &&
      this.lastLineSize &&
      this.lastLineSize[0] === w &&
      this.lastLineSize[1] === h
    ) {
      return;
    }
    const isInitialObservation = !this.lastLineSize && Boolean(this.maskAnimator);
    this.lastLineSize = [w, h];
    if (isInitialObservation) return;
    this.updateMaskImageSync();
  }

  
  measureWords() {
    const words = this.splittedWords;
    if (words.length === 0) return;
    const firstEl = words[0].mainElement;
    const padding = firstEl ? Number.parseFloat(getComputedStyle(firstEl).paddingLeft) || 0 : 0;
    for (const word of words) {
      const el = word.mainElement;
      if (el) {
        word.padding = padding;
        
        
        word.width = Math.max(0, el.clientWidth - padding * 2);
        word.height = Math.max(0, el.clientHeight - padding * 2);
      } else {
        word.width = 0;
        word.height = 0;
        word.padding = 0;
      }
    }
  }

  
  computeMaskSignature(containerWidth, maxEndTime) {
    let signature = `${this.splittedWords.length}|${this.lyricLine.startTime}|${maxEndTime}|${containerWidth}|${WORD_FADE_WIDTH}|${supportMaskImage ? 1 : 0}|${this.lyricPlayer.isNonDynamic ? 1 : 0}`;
    for (const word of this.splittedWords) {
      signature += `|${word.width},${word.height},${word.padding}`;
    }
    return signature;
  }

  
  updateMaskImageSync() {
    
    if (!this.element.isConnected) {
      this.invalidateMask();
      return;
    }

    
    
    
    
    
    
    
    
    
    
    if (this.mainEl.clientWidth <= 0) {
      this.brightness.sync();
      return;
    }

    const mainStyle = getComputedStyle(this.mainEl);
    this.measureWords();
    
    this.brightness.captureGeometry();

    
    const maxEndTime = Math.max(
      0,
      ...this.splittedWords.map(w => w.endTime),
      this.lyricLine.endTime
    );

    const containerWidth = this.balancer ? this.balancer.getContainerWidth(mainStyle) : 0;
    const signature = this.computeMaskSignature(containerWidth, maxEndTime);

    
    if (this.maskAnimator && signature === this.maskSignature) return;
    this.maskSignature = signature;

    if (this.balancer && wordSegmenter) {
      this.balancer.balanceLineBreaks(this.splittedWords.length > 0, wordSegmenter);
      
      this.measureWords();
    }

    this.maskAnimator?.dispose();

    if (supportMaskImage && this.splittedWords.length > 0 && !this.lyricLine.isMeta) {
      this.maskAnimator = new WebMaskAnimator(this.splittedWords, {
        lineStartTime: this.lyricLine.startTime,
        lineEndTime: maxEndTime,
        wordFadeWidth: WORD_FADE_WIDTH
      });
      this.maskAnimator.apply();
    } else {
      this.maskAnimator = undefined;
    }

    this.brightness.sync(true);

    if (this.isEnabled) {
      this.enable(this.lyricPlayer.getCurrentTime(), this.lyricPlayer.getIsPlaying());
    }
  }

  
  invalidateMask() {
    this.maskAnimator?.dispose();
    this.maskAnimator = undefined;
    this.maskSignature = "";
    this.lastLineSize = undefined;
  }

  setTransform(scale, delay, mode = 0, inBrightnessWindow = true) {
    this.scale = scale;
    this.delay = delay;

    
    
    const isColdActivation =
      this.renderMode !== 1 && mode === 1 && !this.brightness.isReady;

    this.setRenderMode(mode === 1);

    
    this.brightness.setInWindow(inBrightnessWindow);

    if (isColdActivation) {
      this.brightness.playActivationTransition();
    }

    if (this.lyricPlayer.getEnableSpring()) {
      
      this.lineTransforms.scale.setTargetPosition(scale);
    } else {
      this.lineTransforms.scale.setPosition(scale);
    }
    this.isUiDirty = true;
  }

  update(delta) {
    if (!this.lyricPlayer.getEnableSpring()) return;
    const scaleMoving = !this.lineTransforms.scale.arrived();
    this.lineTransforms.scale.update(delta);
    if (scaleMoving) this.isUiDirty = true;
  }

  commitChanges() {
    if (this.isUiDirty) {
      this.rebuildStyle();
      this.isUiDirty = false;
    }
  }

  rebuildStyle() {
    const currentScale = this.lineTransforms.scale.getCurrentPosition() / 100;
    if (Math.abs(currentScale - this.lastScaleNum) >= 0.0001) {
      this.lastScaleNum = currentScale;
      this.element.style.transform = `scale(${currentScale.toFixed(3)})`;
    }
  }

  disposeElements() {
    this.brightness.deactivate();
    this.balancer?.reset();
    this.invalidateMask();
    for (const realWord of this.splittedWords) {
      for (const a of realWord.elementAnimations) a.cancel();
      realWord.elementAnimations = [];
      for (const sub of realWord.subElements) {
        sub.remove();
      }
      realWord.subElements = [];
      if (realWord.mainElement?.parentNode) {
        realWord.mainElement.parentNode.removeChild(realWord.mainElement);
      }
    }
    this.splittedWords = [];
    this.mainEl.innerHTML = "";
  }

  dispose() {
    this.brightness.dispose();
    this.disposeElements();
    this.element.remove();
  }
}






class LyricGroup {
  constructor(lyricPlayer, mainLine) {
    this.lyricPlayer = lyricPlayer;
    this.mainLine = mainLine;
    this.bgLine = undefined;
    this.bgWrapper = undefined;

    this.element = document.createElement("div");
    this.element.className = "lyric-line-wrapper";
    if (mainLine.getLine().isDuet) {
      this.element.classList.add("is-duet-wrapper");
    }
    this.element.appendChild(mainLine.getElement());

    this.posY = new Spring(0, { ...POS_Y_SPRING_DEFAULT });
    this.bgSlideY = new Spring(-80, { ...POS_Y_SPRING_DEFAULT });
    this.posY.setPosition(window.innerHeight * 2);
    this.bgSlideY.setPosition(-80);

    this.top = 0;
    this.delay = 0;
    this.isActive = false;
    this.opacity = 1;
    this.blur = 0;
    this.isBgFirst = false;
    
    this.inBrightnessWindow = true;

    this.isUiDirty = true;
    this.lastYNum = -9999;
    this.lastOpacityNum = -1;
    this.lastBlurNum = -1;
    this.lastBgSlideYNum = -9999;
    this.lastBgHeight = 0;
    this.lastBgIsHidden = undefined;
    this.lastIsActive = undefined;
  }

  get startTime() {
    return this.mainLine.getLine().startTime;
  }

  get endTime() {
    return this.mainLine.getLine().endTime;
  }

  getElement() {
    return this.element;
  }

  get isInSight() {
    const t = this.posY.getCurrentPosition();
    const index = this.lyricPlayer.lyricGroups.indexOf(this);
    const h = index !== -1
      ? this.lyricPlayer.getLineHeight(index)
      : this.lyricPlayer.defaultLineHeight;
    const pb = this.lyricPlayer.size[1];
    const ov = this.lyricPlayer.overscanPx;
    
    return t < pb + ov && t + h > -ov;
  }

  
  isInViewportRange() {
    const t = this.posY.getCurrentPosition();
    const index = this.lyricPlayer.lyricGroups.indexOf(this);
    const h = index !== -1
      ? this.lyricPlayer.getLineHeight(index)
      : this.lyricPlayer.defaultLineHeight;
    const pb = this.lyricPlayer.size[1];
    return t < pb && t + h > 0;
  }

  show() {
    if (!this.element.parentElement) {
      const playerEl = this.lyricPlayer.getElement();
      const groups = this.lyricPlayer.lyricGroups;
      const myIndex = groups.indexOf(this);
      let referenceNode = null;
      if (myIndex !== -1) {
        for (let i = myIndex + 1; i < groups.length; i++) {
          if (groups[i].element.parentElement === playerEl) {
            referenceNode = groups[i].element;
            break;
          }
        }
      }
      playerEl.insertBefore(this.element, referenceNode);
      
      this.lyricPlayer.resizeObserver.observe(this.element);
      if (this.bgWrapper) {
        this.lyricPlayer.resizeObserver.observe(this.bgWrapper);
      }
    }
    this.mainLine.show();
    this.bgLine?.show();
  }

  hide() {
    if (this.element.parentElement) {
      this.mainLine.hide();
      this.bgLine?.hide();
      
      
      
      
      try { this.lyricPlayer.resizeObserver?.unobserve(this.element); } catch (e) {  }
      if (this.bgWrapper) {
        try { this.lyricPlayer.resizeObserver?.unobserve(this.bgWrapper); } catch (e) {  }
      }
      this.element.remove();
    }
  }

  addBgLine(bgLine) {
    if (this.bgLine) {
      this.bgLine.dispose();
    }
    if (this.bgWrapper) {
      this.bgWrapper.remove();
    }
    this.bgLine = bgLine;

    // 元信息行的背景行常驻显示(元信息行本身不随时间高亮/滚动)
    const mainData = this.mainLine.getLine();
    this.bgAlwaysActive = !!(mainData && mainData.isMeta);

    
    const bgStartTime = bgLine.getLine().words[0]?.startTime ?? bgLine.getLine().startTime;
    const mainStartTime = this.mainLine.getLine().words[0]?.startTime ?? this.mainLine.getLine().startTime;
    this.isBgFirst = bgStartTime < mainStartTime;

    if (this.mainLine.getLine().isDuet) {
      bgLine.getElement().classList.add("duet");
      this.element.classList.add("is-duet-wrapper");
    }

    this.bgWrapper = document.createElement("div");
    this.bgWrapper.className = "bg-wrapper";
    this.bgWrapper.appendChild(bgLine.getElement());

    const shouldBgFirst = this.isBgFirst;
    if (shouldBgFirst) {
      this.bgWrapper.classList.add("bg-top");
      this.element.insertBefore(this.bgWrapper, this.mainLine.getElement());
      this.bgSlideY.setPosition(80);
    } else {
      this.element.appendChild(this.bgWrapper);
    }
    
    this.lyricPlayer.groupElementMap.set(this.bgWrapper, this);
    if (this.element.parentElement) {
      this.lyricPlayer.resizeObserver.observe(this.bgWrapper);
    }
    this.lastBgHeight = this.bgWrapper.clientHeight || 0;
  }

  setTransform(top, immediate, delay, isActive, opacity, blur, inBrightnessWindow = true) {
    this.top = top;
    this.delay = delay;
    this.isActive = isActive;
    this.opacity = opacity;
    this.blur = blur;
    this.inBrightnessWindow = inBrightnessWindow;

    
    const isPlaying = this.lyricPlayer.getIsPlaying();
    const enableScale = this.lyricPlayer.getEnableScale();
    const renderMode = isActive ? 1 : 0;
    const scaleAspect = enableScale ? SCALE_ASPECT_MAIN : 100;
    let mainScale = 100;
    if (!isActive && isPlaying) mainScale = scaleAspect;
    let bgScale = 100;
    if (!isActive && isPlaying) bgScale = SCALE_ASPECT_BG;
    this.mainLine.setTransform(mainScale, delay, renderMode, inBrightnessWindow);
    this.bgLine?.setTransform(bgScale, delay, renderMode, inBrightnessWindow);

    
    const enableSpring = this.lyricPlayer.getEnableSpring();

    
    const shouldBgFirst = this.isBgFirst;
    const hiddenSlideY = shouldBgFirst ? 80 : -80;
    // 元信息行的背景行常驻显示: 元信息行本身不随时间高亮/滚动, 背景行也不该只在暂停时露出来
    const isMetaLine = !!(this.mainLine && this.mainLine.getLine && this.mainLine.getLine().isMeta);
    const targetBgSlideY = isActive || !isPlaying || isMetaLine ? 0 : hiddenSlideY;

    if (immediate || !enableSpring) {
      this.posY.setPosition(top);
      this.bgSlideY.setPosition(targetBgSlideY);
    } else {
      this.posY.setTargetPosition(top, delay);
      this.bgSlideY.setTargetPosition(targetBgSlideY, delay);
    }
    this.isUiDirty = true;
  }

  update(delta) {
    if (this.lyricPlayer.getEnableSpring()) {
      const posMoving = !this.posY.arrived();
      const bgMoving = !this.bgSlideY.arrived();
      this.posY.update(delta);
      this.bgSlideY.update(delta);
      if (posMoving || bgMoving) this.isUiDirty = true;
    }
    this.mainLine.update(delta);
    this.bgLine?.update(delta);
  }

  commitChanges() {
    if (this.isInSight) {
      this.show();
      if (this.isUiDirty) {
        this.renderStyles();
        this.isUiDirty = false;
      }
      this.mainLine.commitChanges();
      this.bgLine?.commitChanges();
    } else {
      this.hide();
    }
  }

  renderStyles() {
    const style = this.element.style;

    const currentY = this.posY.getCurrentPosition();
    if (Math.abs(currentY - this.lastYNum) >= 0.001) {
      this.lastYNum = currentY;
      style.transform = `translateY(${currentY.toFixed(1)}px)`;
    }

    if (Math.abs(this.opacity - this.lastOpacityNum) >= 0.05) {
      this.lastOpacityNum = this.opacity;
      style.opacity = String(this.opacity);
    }

    const blurVal = Math.min(5, this.blur);
    if (Math.abs(blurVal - this.lastBlurNum) >= 0.05) {
      this.lastBlurNum = blurVal;
      style.filter = blurVal > 0.01 ? `blur(${blurVal.toFixed(2)}px)` : "none";
    }

    if (this.bgWrapper) {
      const bgActiveNow = this.isActive || !!this.bgAlwaysActive;
      if (this.lastIsActive !== bgActiveNow) {
        this.lastIsActive = bgActiveNow;
        this.bgWrapper.classList.toggle("active", bgActiveNow);
      }

      const bgStyle = this.bgWrapper.style;
      const slideY = this.bgSlideY.getCurrentPosition();
      if (Math.abs(slideY - this.lastBgSlideYNum) >= 0.001) {
        this.lastBgSlideYNum = slideY;
        const activeProgress = clamp01(1 - Math.abs(slideY) / 80);
        const scaleStr = (0.8 + activeProgress * 0.2).toFixed(3);
        const shouldBgFirst = this.isBgFirst;
        const translateYPx = (slideY / 100) * this.lastBgHeight;
        if (shouldBgFirst) {
          const currentMarginTop = -this.lastBgHeight * (1 - activeProgress);
          bgStyle.marginTop = `${currentMarginTop.toFixed(1)}px`;
        } else {
          bgStyle.marginTop = "";
        }
        bgStyle.transform = `translateY(${translateYPx.toFixed(1)}px) scale(${scaleStr})`;

        const targetHiddenY = shouldBgFirst ? 80 : -80;
        const isHidden = Math.abs(slideY - targetHiddenY) < 0.1 && !this.isActive;
        if (this.lastBgIsHidden !== isHidden) {
          this.lastBgIsHidden = isHidden;
          this.bgWrapper.classList.toggle("hidden", isHidden);
        }
      }
    }
  }

  enable(time, shouldPlay) {
    this.mainLine.enable(time, shouldPlay);
    this.bgLine?.enable(time, shouldPlay);
    if (this._zeroDurLine()) this.mainLine.brightness?.setMainBright(true);
  }

  disable() {
    this.mainLine.disable();
    this.bgLine?.disable();
    if (this._zeroDurLine()) this.mainLine.brightness?.setMainBright(false);
  }

  _zeroDurLine() {
    const l = this.mainLine.getLine();
    return !!(l && !l.isMeta && l.words && l.words.length && l.words.every(w => w.endTime <= w.startTime));
  }

  onLineSizeChange(size) {
    this.mainLine.onLineSizeChange(size);
    this.bgLine?.onLineSizeChange(size);
  }

  
  onBgSizeChange(size) {
    if (this.bgWrapper && this.lastBgHeight !== size[1]) {
      this.lastBgHeight = size[1];
      this.lastBgSlideYNum = -9999;
      this.isUiDirty = true;
    }
  }

  dispose() {
    try { this.lyricPlayer.resizeObserver?.unobserve(this.element); } catch (e) {  }
    if (this.bgWrapper) {
      try { this.lyricPlayer.resizeObserver?.unobserve(this.bgWrapper); } catch (e) {  }
      this.lyricPlayer.groupElementMap.delete(this.bgWrapper);
    }
    this.mainLine.dispose();
    this.bgLine?.dispose();
    this.element.remove();
  }
}





class BottomLineEl {
  constructor(lyricPlayer) {
    this.lyricPlayer = lyricPlayer;
    this.element = document.createElement("div");
    this.element.className = "lyric-line-wrapper bottom-line-wrapper";
    this.contentEl = document.createElement("div");
    this.contentEl.className = "lyric-line bottom-line";
    this.contentEl.dataset.bottomLine = "true";
    this.element.appendChild(this.contentEl);
    this.posY = new Spring(0, { ...POS_Y_SPRING_DEFAULT });
    this.posY.setPosition(window.innerHeight * 2);
    this.blur = 0;
    this.top = 0;
    this.lineSize = [0, 0];
    this.isFocused = false;
    this.lastYNum = -9999;
    this.lastBlurNum = -1;
    this.isUiDirty = true;
  }

  getElement() { return this.element; }
  getContentElement() { return this.contentEl; }

  setFocused(focused) {
    if (this.isFocused !== focused) {
      this.isFocused = focused;
      
      
      this.contentEl.classList.toggle("gradient-mask", focused);
      if (focused) {
        this.element.dataset.focused = "true";
      } else {
        delete this.element.dataset.focused;
      }
    }
  }

  setTransform(top, blur, immediate, delay) {
    this.top = top;
    this.blur = blur;
    if (immediate) {
      this.posY.setPosition(top);
    } else {
      this.posY.setTargetPosition(top, delay);
    }
    this.isUiDirty = true;
  }

  resetPosition() {
    this.posY.setPosition(window.innerHeight * 2);
  }

  update(delta) {
    const moving = !this.posY.arrived();
    this.posY.update(delta);
    if (moving) this.isUiDirty = true;
  }

  commitChanges() {
    if (!this.isUiDirty) return;
    this.isUiDirty = false;
    const style = this.element.style;
    const currentY = this.posY.getCurrentPosition();
    if (Math.abs(currentY - this.lastYNum) >= 0.001) {
      this.lastYNum = currentY;
      style.transform = `translateY(${currentY.toFixed(1)}px)`;
    }
    const blurVal = Math.min(5, this.blur);
    if (Math.abs(blurVal - this.lastBlurNum) >= 0.05) {
      this.lastBlurNum = blurVal;
      style.filter = blurVal > 0.01 ? `blur(${blurVal.toFixed(2)}px)` : "none";
    }
  }
}




const DOT3_TRAILING_MS = 750;
const EXIT_PHASE1_MS = 750;
const EXIT_PHASE2_MS = 250;
const EXIT_TOTAL_MS = EXIT_PHASE1_MS + EXIT_PHASE2_MS;
const EXIT_FADE_MS = 250;
const DISMISS_FADE_MS = 150;
const ENTER_HOLD_MS = 500;
const ENTER_FADE_MS = 180;
const DOT_ENTER_FADE_MS = 750;
const DOT_ENTER_STAGGER_MS = 80;
const DOT_ENTER_TOTAL_MS = (3 - 1) * DOT_ENTER_STAGGER_MS + DOT_ENTER_FADE_MS;
const BREATHE_BASE_PERIOD_MS = 4000;
const FALLBACK_HOLD_THRESHOLD_MS = 3000;
const BREATHE_MAX_SCALE = 1.25;
const BREATHE_MIN_SCALE = 0.4;
const DOT_INACTIVE_OPACITY = 0.2;
const DOT_ACTIVE_OPACITY = 0.9;
const DOT_COUNT = 3;

const lightingEasing = makeBezier(0.56, 0.01, 0.45, 1);
const enterFadeEasing = makeBezier(0.59, 0.02, 0.07, 1);
const exitPhase1Easing = makeBezier(0.14, 0.06, 0.25, 1);
const exitPhase2Easing = makeBezier(0.29, 0.03, 1, 0.38);
const exitFadeEasing = makeBezier(0.43, 0.08, 0.83, 0.31);



function breathingProgress(t) {
  if (t <= 0) return 0;
  if (t >= 1) return 1;
  const angle = 4.0 * Math.PI * t;
  const s = Math.sin(angle);
  const c = Math.cos(angle);
  return t - 0.084 * s + 0.008 * (1 - c) + 0.0046 * s * (c - s);
}

function dotOpacity(fraction) {
  return DOT_INACTIVE_OPACITY + (DOT_ACTIVE_OPACITY - DOT_INACTIVE_OPACITY) * clamp01(fraction);
}

function enterOpacity(internalMs) {
  return enterFadeEasing(clamp01(internalMs / ENTER_FADE_MS));
}

function dotEnterAlpha(index, internalMs) {
  const t = clamp01((internalMs - index * DOT_ENTER_STAGGER_MS) / DOT_ENTER_FADE_MS);
  return t * t;
}

function computeDotFraction(startDelay, duration, internalMs, target) {
  if (internalMs <= startDelay) return 0;
  const localT = (internalMs - startDelay) / duration;
  return lightingEasing(clamp01(localT)) * target;
}

class InterludeDots {
  constructor(element) {
    this.element = element;
    this.dots = Array.from(element.querySelectorAll("span"));
    this.posY = new Spring(0, { ...POS_Y_SPRING_DEFAULT });
    this.shouldSnapPosY = true;
    this.left = 0;
    this.top = 0;
    this.currentTime = 0;
    this.playing = true;
    this.phase = "idle";
    this.mode = "breathe";
    this.startTime = 0;
    this.endTime = 0;
    this.anchorTime = 0;
    this.delayEndMs = 0;
    this.bodyEndMs = 0;
    this.totalEndMs = 0;
    this.breathePeriodMs = BREATHE_BASE_PERIOD_MS;
    this.segmentMs = 0;
    this.dot3DurationMs = 0;
    this.dot3Target = 0;
    this.fadeElapsedMs = 0;
    this.fadeInitialOpacity = 0;
    this.snapshot = {
      isActive: true,
      dotOpacities: [0, 0, 0],
      scale: 1,
      opacity: 0
    };
    
    this.lastStyle = "";
    this.lastDotOpacities = ["", "", ""];
    this.element.style.opacity = "0";
    
    this._geomW = -1;
    this._padLeftPx = 0;
    this.anchorRight = false;
  }

  getElement() { return this.element; }

  



  setInterlude(interlude, currentTime, forceReset, anchorLineIndex) {
    const [startTime, endTime] = interlude;
    const isSameInterlude = this.startTime === startTime && this.endTime === endTime;
    if (!forceReset && isSameInterlude && this.phase !== "fading") {
      return this.phase === "performing";
    }

    this.cancelFadeOut();
    this.startTime = startTime;
    this.endTime = endTime;
    this.currentTime = currentTime ?? startTime;

    if (forceReset) {
      this.anchorTime = this.currentTime;
      this.delayEndMs = ENTER_HOLD_MS;
    } else {
      this.anchorTime = startTime;
      this.delayEndMs = anchorLineIndex === -1 ? 0 : ENTER_HOLD_MS;
    }

    const remainingMs = Math.max(0, endTime - this.anchorTime);
    const bodyMs = remainingMs - this.delayEndMs - EXIT_TOTAL_MS;

    if (bodyMs < DOT_ENTER_TOTAL_MS) {
      
      this.hidePerformance();
      return false;
    }

    this.bodyEndMs = this.delayEndMs + bodyMs;
    this.totalEndMs = this.bodyEndMs + EXIT_TOTAL_MS;

    if (bodyMs < FALLBACK_HOLD_THRESHOLD_MS) {
      
      this.mode = "fallback-hold";
      this.dot3Target = 1.0;
    } else {
      
      this.mode = "breathe";
      const breatheCycles = Math.max(1, Math.floor(bodyMs / BREATHE_BASE_PERIOD_MS));
      this.breathePeriodMs = bodyMs / breatheCycles;
      this.segmentMs = Math.round((bodyMs + DOT3_TRAILING_MS) / DOT_COUNT);
      this.dot3DurationMs = bodyMs - this.segmentMs * 2;
      this.dot3Target = this.dot3DurationMs / this.segmentMs;
    }

    this.enterPerforming();
    return true;
  }

  clearInterlude(immediate = false) {
    this.startTime = 0;
    this.endTime = 0;
    this.dismiss(immediate);
  }

  dismiss(immediate = false) {
    if (this.phase === "idle") return;
    if (immediate || !this.playing) {
      this.cancelFadeOut();
      this.hidePerformance();
      return;
    }
    if (this.phase === "fading") return;
    if (this.snapshot.opacity <= 0) {
      this.hidePerformance();
      return;
    }
    this.enterFading();
  }

  setTransform(left = this.left, top = this.top, immediate = false) {
    this.left = left;
    this.top = top;
    
    this.anchorRight = Math.abs(left) > 0.5;
    this.measureAnchorGeometry();
    const shouldAnimate = !immediate && this.phase !== "idle" && !this.shouldSnapPosY;
    if (shouldAnimate) {
      this.posY.setTargetPosition(top);
    } else {
      this.shouldSnapPosY = false;
      this.posY.setPosition(top);
    }
    this.update(0);
  }

  pause() {
    this.playing = false;
    if (this.phase === "fading") {
      this.hidePerformance();
    }
  }

  resume() {
    this.playing = true;
  }

  syncClock(time) {
    this.currentTime = time;
  }

  update(delta = 0) {
    if (this.phase === "idle") return;
    if (this.phase === "fading") {
      this.updateFadeOut(delta);
      return;
    }
    if (this.playing) {
      this.currentTime += delta * 1000;
    }
    const elapsed = Math.max(0, this.currentTime - this.anchorTime);
    const snapshot = this.resolveSnapshot(elapsed);
    this.posY.update(delta);
    this.render(snapshot, this.left, this.posY.getCurrentPosition());
    if (!snapshot.isActive) {
      this.enterIdle();
    }
  }

  enterPerforming() {
    this.mode = this.mode;
    this.phase = "performing";
    this.shouldSnapPosY = true;
  }

  enterFading() {
    this.fadeElapsedMs = 0;
    this.fadeInitialOpacity = this.snapshot.opacity;
    this.phase = "fading";
  }

  enterIdle() {
    this.phase = "idle";
  }

  cancelFadeOut() {
    if (this.phase === "fading") {
      this.enterIdle();
    }
  }

  hidePerformance() {
    const wasActive = this.phase !== "idle";
    this.enterIdle();
    if (wasActive) {
      this.render({ isActive: false, dotOpacities: [0, 0, 0], scale: 1, opacity: 0 },
        this.left, this.posY.getCurrentPosition());
    }
  }

  updateFadeOut(delta) {
    this.fadeElapsedMs += delta * 1000;
    const progress = clamp01(this.fadeElapsedMs / DISMISS_FADE_MS);
    if (progress >= 1) {
      this.hidePerformance();
      return;
    }
    this.snapshot.opacity = this.fadeInitialOpacity * (1 - exitFadeEasing(progress));
    this.snapshot.isActive = true;
    this.posY.update(delta);
    this.render(this.snapshot, this.left, this.posY.getCurrentPosition());
  }

  resolveSnapshot(elapsed) {
    const elapsedMs = elapsed;
    if (elapsedMs >= this.totalEndMs) {
      this.snapshot.isActive = false;
      this.snapshot.scale = 1;
      this.snapshot.opacity = 0;
      this.snapshot.dotOpacities[0] = 0;
      this.snapshot.dotOpacities[1] = 0;
      this.snapshot.dotOpacities[2] = 0;
      return this.snapshot;
    }

    this.snapshot.isActive = true;

    
    if (elapsedMs < this.delayEndMs) {
      this.snapshot.opacity = 0;
      this.snapshot.scale = 1;
      this.snapshot.dotOpacities[0] = 0;
      this.snapshot.dotOpacities[1] = 0;
      this.snapshot.dotOpacities[2] = 0;
      return this.snapshot;
    }

    const internalMs = elapsedMs - this.delayEndMs;
    const fractionAt = (startDelay, duration, target) =>
      computeDotFraction(startDelay, duration, internalMs, target);

    
    if (elapsedMs >= this.bodyEndMs) {
      const exitElapsedMs = elapsedMs - this.bodyEndMs;
      const fadeT = clamp01((exitElapsedMs - (EXIT_TOTAL_MS - EXIT_FADE_MS)) / EXIT_FADE_MS);
      this.snapshot.opacity = enterOpacity(internalMs) * (1 - exitFadeEasing(fadeT));

      if (exitElapsedMs < EXIT_PHASE1_MS) {
        
        this.snapshot.scale = 1 + exitPhase1Easing(exitElapsedMs / EXIT_PHASE1_MS) * (BREATHE_MAX_SCALE - 1);
      } else {
        
        const phase2T = clamp01((exitElapsedMs - EXIT_PHASE1_MS) / EXIT_PHASE2_MS);
        this.snapshot.scale = BREATHE_MAX_SCALE - exitPhase2Easing(phase2T) * (BREATHE_MAX_SCALE - BREATHE_MIN_SCALE);
      }

      const trailing = clamp01(exitElapsedMs / DOT3_TRAILING_MS);
      this.writeDotOpacities(internalMs, [1, 1, this.dot3Target + (1 - this.dot3Target) * trailing]);
      return this.snapshot;
    }

    
    this.snapshot.opacity = enterOpacity(internalMs);

    if (this.mode === "fallback-hold") {
      this.snapshot.scale = 1;
      this.writeDotOpacities(internalMs, [1, 1, 1]);
      return this.snapshot;
    }

    const cycleT = (internalMs % this.breathePeriodMs) / this.breathePeriodMs;
    const progress = breathingProgress(cycleT);
    this.snapshot.scale = progress <= 0.5
      ? 1 + (progress / 0.5) * (BREATHE_MAX_SCALE - 1)
      : BREATHE_MAX_SCALE - ((progress - 0.5) / 0.5) * (BREATHE_MAX_SCALE - 1);

    this.writeDotOpacities(internalMs, [
      fractionAt(0, this.segmentMs, 1),
      fractionAt(this.segmentMs, this.segmentMs, 1),
      fractionAt(this.segmentMs * 2, this.dot3DurationMs, this.dot3Target)
    ]);
    return this.snapshot;
  }

  writeDotOpacities(internalMs, fractions) {
    this.snapshot.dotOpacities[0] = dotOpacity(fractions[0]) * dotEnterAlpha(0, internalMs);
    this.snapshot.dotOpacities[1] = dotOpacity(fractions[1]) * dotEnterAlpha(1, internalMs);
    this.snapshot.dotOpacities[2] = dotOpacity(fractions[2]) * dotEnterAlpha(2, internalMs);
  }

  measureAnchorGeometry() {
    
    
    const w = this.element.offsetWidth;
    if (w !== this._geomW) {
      this._geomW = w;
      this._padLeftPx = parseFloat(getComputedStyle(this.element).paddingLeft) || 0;
    }
  }

  render(snapshot, left, top) {
    
    
    
    
    
    
    
    
    const scale = snapshot.scale;
    let tx = left;
    if (scale !== 1) {
      const w = this._geomW > 0 ? this._geomW : (this._geomW = this.element.offsetWidth);
      if (w > 0) {
        const lever = w / 2 - this._padLeftPx;
        tx = left + (this.anchorRight ? -1 : 1) * (scale - 1) * lever;
      }
    }
    const curStyle =
      `transform:translate(${tx.toFixed(2)}px, ${top.toFixed(2)}px)` +
      ` scale(${scale.toFixed(4)});opacity:${snapshot.opacity.toFixed(3)}`;
    for (let i = 0; i < 3; i++) {
      const o = snapshot.dotOpacities[i].toFixed(3);
      if (this.lastDotOpacities[i] !== o) {
        this.lastDotOpacities[i] = o;
        this.dots[i].style.opacity = o;
      }
    }
    if (this.lastStyle !== curStyle) {
      this.lastStyle = curStyle;
      this.element.setAttribute("style", curStyle);
    }
  }

  dispose() {
    this.dismiss(true);
  }
}





const SEEK_JITTER_TOLERANCE = 150;
const SEEK_DRIFT_SLACK = 0.5;
const SEEK_MAX_TRUSTED_GAP = 800;


class SeekDetector {
  constructor(now = () => performance.now()) {
    this.now = now;
    this.lastMediaTime = 0;
    this.lastWallTime = 0;
    this.hasBaseline = false;
  }

  detect(time, isPlaying) {
    const wall = this.now();
    if (!this.hasBaseline) {
      this.rebase(time, wall);
      this.hasBaseline = true;
      return false;
    }
    
    if (time < this.lastMediaTime) {
      this.rebase(time, wall);
      return true;
    }
    const mediaDelta = time - this.lastMediaTime;
    const elapsed = Math.max(0, wall - this.lastWallTime);
    const wallDelta = Math.min(elapsed, SEEK_MAX_TRUSTED_GAP);
    this.rebase(time, wall);
    
    const expected = isPlaying ? wallDelta : 0;
    const tolerance = isPlaying
      ? Math.max(SEEK_JITTER_TOLERANCE, wallDelta * SEEK_DRIFT_SLACK)
      : SEEK_JITTER_TOLERANCE;
    const drift = mediaDelta - expected;
    return drift > tolerance;
  }

  reset() {
    this.hasBaseline = false;
    this.lastMediaTime = 0;
    this.lastWallTime = 0;
  }

  rebase(time, wall) {
    this.lastMediaTime = time;
    this.lastWallTime = wall;
  }
}





const MIN_INTERLUDE_GAP = 7000;

class Timeline {
  constructor() {
    this.lyricBounds = [];
    this.precalculatedInterludes = [];
    this.maxEndTime = 0;
    this.playbackCursor = 0;
    this.interludeCursor = 0;
    this.lrcMode = false;
    this.playingGroupsSet = new Set();
    this.highlightedGroupsSet = new Set();
    this.nextPlayingSet = new Set();
    this.nextHighlightedSet = new Set();
    this.snapshot = {
      currentTime: 0,
      highlightedGroups: this.highlightedGroupsSet,
      scrollToIndex: 0,
      latestHighlightedIndex: undefined,
      activeInterlude: undefined,
      isFocusOnInterlude: false,
      isEndOfSong: false
    };
    this.diff = {
      hasChanged: false,
      isTimeJumped: false,
      addedHighlighted: [],
      removedHighlighted: [],
      isInterludeChanged: false,
      isScrollToChanged: false,
      isEndOfSongChanged: false
    };
    this.addedPlayingIds = [];
    this.removedPlayingIds = [];
    this.addedHighlightedIds = [];
    this.removedHighlightedIds = [];
    this.expiredHighlightedIds = [];
  }

  setTimeBounds(bounds) {
    this.lyricBounds = bounds;
    if (this.lrcMode) {
      for (let i = 0; i < this.lyricBounds.length - 1; i++) {
        const cur = this.lyricBounds[i];
        const next = this.lyricBounds[i + 1];
        if (cur.isMeta || next.isMeta) continue;
        if (next.startTime > cur.endTime) {
          cur.endTime = next.startTime;
        }
      }
    }
    this.precalculatedInterludes = this.calculateInterludes(this.lyricBounds);
    let maxEnd = 0;
    for (const bound of bounds) {
      if (bound.endTime > maxEnd) maxEnd = bound.endTime;
    }
    this.maxEndTime = maxEnd;
    this.reset();
  }

  getSnapshot() {
    return this.snapshot;
  }

  reset() {
    this.playbackCursor = 0;
    this.interludeCursor = 0;
    this.playingGroupsSet.clear();
    this.highlightedGroupsSet.clear();
    this.nextPlayingSet.clear();
    this.nextHighlightedSet.clear();
    this.snapshot.currentTime = 0;
    this.snapshot.scrollToIndex = 0;
    this.snapshot.latestHighlightedIndex = undefined;
    this.snapshot.activeInterlude = undefined;
    this.snapshot.isFocusOnInterlude = false;
    this.snapshot.isEndOfSong = false;
  }

  sync(time, forceSeek = false) {
    this.addedPlayingIds.length = 0;
    this.removedPlayingIds.length = 0;
    this.addedHighlightedIds.length = 0;
    this.removedHighlightedIds.length = 0;

    const prevInterlude = this.snapshot.activeInterlude;
    const prevFocusOnInterlude = this.snapshot.isFocusOnInterlude;
    const prevScrollToIndex = this.snapshot.scrollToIndex;
    const prevEndOfSong = this.snapshot.isEndOfSong;

    
    const isTimeRetreating = time < this.snapshot.currentTime;
    const isJump = forceSeek || isTimeRetreating;

    const activeInterlude = this.resolveActiveInterlude(time, isJump);
    this.snapshot.activeInterlude = activeInterlude;

    const isPastLastLine = this.lyricBounds.length > 0 && time >= this.maxEndTime;

    if (isJump) {
      this.performSeek(time, !!activeInterlude || isPastLastLine);
    } else {
      this.performPlayback(time);
    }

    
    if (activeInterlude && this.playingGroupsSet.size === 0) {
      this.flushAllHighlighted();
    }
    if (isPastLastLine) {
      this.flushAllHighlighted();
    }

    this.updateInterludeFocus(activeInterlude);

    const isInterludeChanged = prevInterlude !== activeInterlude;
    const isFocusChanged = prevFocusOnInterlude !== this.snapshot.isFocusOnInterlude;
    const isScrollToChanged = prevScrollToIndex !== this.snapshot.scrollToIndex;
    const isEndOfSongChanged = isPastLastLine !== prevEndOfSong;

    const hasChanged =
      isJump ||
      this.addedPlayingIds.length > 0 ||
      this.removedPlayingIds.length > 0 ||
      this.addedHighlightedIds.length > 0 ||
      this.removedHighlightedIds.length > 0 ||
      isInterludeChanged ||
      isFocusChanged ||
      isScrollToChanged ||
      isEndOfSongChanged;

    this.snapshot.currentTime = time;

    if (this.highlightedGroupsSet.size > 0) {
      let maxIndex = -1;
      for (const id of this.highlightedGroupsSet) {
        if (id > maxIndex) maxIndex = id;
      }
      this.snapshot.latestHighlightedIndex = maxIndex;
    } else {
      this.snapshot.latestHighlightedIndex = undefined;
    }

    this.snapshot.isEndOfSong = isPastLastLine;

    this.diff.hasChanged = hasChanged;
    this.diff.isTimeJumped = isJump;
    this.diff.isInterludeChanged = isInterludeChanged;
    this.diff.isScrollToChanged = isScrollToChanged;
    this.diff.isEndOfSongChanged = isEndOfSongChanged;
    this.diff.addedHighlighted = [...this.addedHighlightedIds];
    this.diff.removedHighlighted = [...this.removedHighlightedIds];
    return this.diff;
  }

  
  performPlayback(time) {
    
    for (const lastPlayingId of this.playingGroupsSet) {
      const bound = this.lyricBounds[lastPlayingId];
      if (!bound || time < bound.startTime || bound.endTime <= time) {
        this.playingGroupsSet.delete(lastPlayingId);
        this.removedPlayingIds.push(lastPlayingId);
      }
    }

    
    let cursor = Math.max(0, this.playbackCursor);
    const len = this.lyricBounds.length;
    while (cursor < len) {
      const bound = this.lyricBounds[cursor];
      if (bound.startTime > time) break;
      if (bound.startTime <= time && bound.endTime > time && !this.playingGroupsSet.has(cursor)) {
        this.playingGroupsSet.add(cursor);
        this.addedPlayingIds.push(cursor);
      }
      cursor++;
    }
    this.playbackCursor = cursor;

    
    this.expiredHighlightedIds.length = 0;
    for (const id of this.highlightedGroupsSet) {
      if (!this.playingGroupsSet.has(id)) {
        this.expiredHighlightedIds.push(id);
      }
    }

    const addedPlayingCount = this.addedPlayingIds.length;
    const expiredCount = this.expiredHighlightedIds.length;

    
    for (let i = 0; i < addedPlayingCount; i++) {
      const id = this.addedPlayingIds[i];
      this.highlightedGroupsSet.add(id);
      this.addedHighlightedIds.push(id);
    }

    
    if (addedPlayingCount > 0) {
      for (let i = 0; i < expiredCount; i++) {
        const id = this.expiredHighlightedIds[i];
        this.highlightedGroupsSet.delete(id);
        this.removedHighlightedIds.push(id);
      }
      let minHighlighted = Number.POSITIVE_INFINITY;
      for (const id of this.highlightedGroupsSet) {
        if (id < minHighlighted) minHighlighted = id;
      }
      
      this.snapshot.scrollToIndex = this._scrollIndex(minHighlighted);
    }
  }

  
  performSeek(time, dropLingeringWhenIdle) {
    const nextPlaying = this.nextPlayingSet;
    const nextHighlighted = this.nextHighlightedSet;
    nextPlaying.clear();
    nextHighlighted.clear();

    
    let left = 0;
    let right = this.lyricBounds.length - 1;
    let firstGreater = this.lyricBounds.length;
    while (left <= right) {
      const mid = (left + right) >> 1;
      if (this.lyricBounds[mid].startTime > time) {
        firstGreater = mid;
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }

    
    let anchorIndex = -1;
    for (let i = firstGreater - 1; i >= 0; i--) {
      const bound = this.lyricBounds[i];
      if (bound.endTime > bound.startTime) {
        anchorIndex = i;
        break;
      }
    }

    if (anchorIndex === -1) {
      this.playbackCursor = firstGreater;
      this.snapshot.scrollToIndex = 0;
      this.commitSeekDiff();
      return;
    }

    const anchorStart = this.lyricBounds[anchorIndex].startTime;
    let minPlaying = -1;
    let minHighlighted = -1;

    for (let i = anchorIndex; i >= 0; i--) {
      const bound = this.lyricBounds[i];
      
      if (bound.endTime <= anchorStart) continue;
      if (bound.startTime <= time && bound.endTime > time) {
        nextPlaying.add(i);
        minPlaying = i;
      }
      nextHighlighted.add(i);
      minHighlighted = i;
    }

    
    if (dropLingeringWhenIdle && nextPlaying.size === 0) {
      nextHighlighted.clear();
    }

    this.playbackCursor = minPlaying === -1 ? firstGreater : minPlaying;
    
    this.snapshot.scrollToIndex = this._scrollIndex(minHighlighted);

    this.commitSeekDiff();
  }

  _scrollIndex(index) {
    const n = this.lyricBounds.length;
    if (!n) return 0;
    if (!Number.isFinite(index)) return n - 1;
    return clampNum(0, Math.round(index), n - 1);
  }

  commitSeekDiff() {
    
    for (const id of Array.from(this.playingGroupsSet)) {
      if (!this.nextPlayingSet.has(id)) {
        this.playingGroupsSet.delete(id);
        this.removedPlayingIds.push(id);
      }
    }
    for (const id of this.nextPlayingSet) {
      if (!this.playingGroupsSet.has(id)) {
        this.playingGroupsSet.add(id);
        this.addedPlayingIds.push(id);
      }
    }
    for (const id of Array.from(this.highlightedGroupsSet)) {
      if (!this.nextHighlightedSet.has(id)) {
        this.highlightedGroupsSet.delete(id);
        this.removedHighlightedIds.push(id);
      }
    }
    for (const id of this.nextHighlightedSet) {
      if (!this.highlightedGroupsSet.has(id)) {
        this.highlightedGroupsSet.add(id);
        this.addedHighlightedIds.push(id);
      }
    }
  }

  flushAllHighlighted() {
    for (const id of this.highlightedGroupsSet) {
      this.removedHighlightedIds.push(id);
    }
    this.highlightedGroupsSet.clear();
  }

  resolveActiveInterlude(time, isSeek) {
    if (this.precalculatedInterludes.length === 0) return undefined;
    if (isSeek) {
      let cursor = this.precalculatedInterludes.length;
      let left = 0;
      let right = this.precalculatedInterludes.length - 1;
      while (left <= right) {
        const mid = (left + right) >> 1;
        const inter = this.precalculatedInterludes[mid];
        if (inter.endTime > time) {
          cursor = mid;
          right = mid - 1;
        } else {
          left = mid + 1;
        }
      }
      this.interludeCursor = cursor;
      if (cursor < this.precalculatedInterludes.length) {
        const inter = this.precalculatedInterludes[cursor];
        if (time >= inter.startTime && time < inter.endTime) return inter;
      }
      return undefined;
    }
    while (this.interludeCursor < this.precalculatedInterludes.length) {
      const inter = this.precalculatedInterludes[this.interludeCursor];
      if (time >= inter.startTime && time < inter.endTime) return inter;
      if (time >= inter.endTime) {
        this.interludeCursor++;
      } else {
        break;
      }
    }
    return undefined;
  }

  updateInterludeFocus(activeInterlude) {
    this.snapshot.isFocusOnInterlude = !!activeInterlude && this.highlightedGroupsSet.size === 0;
  }

  
  calculateInterludes(bounds) {
    const interludes = [];
    const firstBodyIdx = bounds.findIndex(b => !b.isMeta);
    let maxEnd = 0;
    for (let i = -1; i < bounds.length - 1; i++) {
      if (i >= 0) {
        if (bounds[i].endTime > maxEnd) maxEnd = bounds[i].endTime;
      }
      const gapEnd = Math.max(maxEnd, bounds[i + 1].startTime);
      if (gapEnd - maxEnd >= MIN_INTERLUDE_GAP) {
        // 下一行是元信息(作词/作曲等)时不出间奏圆点: 元信息之前、元信息之间都不触发
        const nextMeta = bounds[i + 1].isMeta;
        if (nextMeta) continue;
        // LRC 只保留"正文第一行之前"的开头间奏, 正文行之间的长间隔照旧不触发
        if (this.lrcMode && i + 1 !== firstBodyIdx) continue;
        interludes.push({
          startTime: maxEnd,
          endTime: gapEnd,
          anchorLineIndex: i
        });
      }
    }
    return interludes;
  }
}






class FocusController {
  constructor() {
    this.target = { type: "line", index: 0 };
  }

  resolve(snapshot, lineCount, flags) {
    const nextTarget = flags.isAutoAlignSuspended
      ? this.resolveSuspendedTarget(snapshot, lineCount, flags)
      : this.resolveActiveTarget(snapshot, lineCount, flags);
    this.target = nextTarget;
    return nextTarget;
  }

  resolveSuspendedTarget(snapshot, lineCount, flags) {
    const target = this.target;
    switch (target.type) {
      case "line":
        return { type: "line", index: this.clampLineIndex(target.index, lineCount) };
      case "interlude": {
        const isInterludeActive =
          snapshot.isFocusOnInterlude &&
          !!snapshot.activeInterlude &&
          flags.canDisplayInterlude;
        if (!isInterludeActive) {
          return { type: "line", index: this.clampLineIndex(target.anchorIndex + 1, lineCount) };
        }
        return target;
      }
      case "bottom":
        if (!flags.hasBottomContent) {
          return { type: "line", index: this.clampLineIndex(lineCount - 1, lineCount) };
        }
        return target;
    }
  }

  resolveActiveTarget(snapshot, lineCount, flags) {
    
    if (snapshot.isFocusOnInterlude && snapshot.activeInterlude) {
      if (!flags.canDisplayInterlude) {
        return {
          type: "line",
          index: this.clampLineIndex(snapshot.activeInterlude.anchorLineIndex + 1, lineCount)
        };
      }
      return { type: "interlude", anchorIndex: snapshot.activeInterlude.anchorLineIndex };
    }
    if (snapshot.isEndOfSong) {
      if (flags.hasBottomContent) return { type: "bottom" };
      return { type: "line", index: this.clampLineIndex(lineCount - 1, lineCount) };
    }
    return { type: "line", index: this.clampLineIndex(snapshot.scrollToIndex, lineCount) };
  }

  clampLineIndex(index, lineCount) {
    if (lineCount <= 0) return 0;
    return clampNum(0, index, lineCount - 1);
  }
}





class LayoutCalculator {
  constructor() {
    this.prefixSums = new Float64Array(0);
    this.heights = new Float64Array(0);
    this.isMeasured = new Uint8Array(0);
    this.instructionPool = [];
    this.isPrefixSumDirty = true;
    this.lyricCount = 0;
    this.totalLyricHeight = 0;
    this.layoutResult = {
      lineCount: 0,
      lineInstructions: this.instructionPool,
      bottomLineY: 0,
      isBottomLineInViewport: false,
      hasInterlude: false,
      interludeY: 0
    };
  }

  initHeights(count, defaultHeight) {
    this.lyricCount = count;
    this.resetLayoutResult();
    if (this.prefixSums.length < count + 1) {
      this.prefixSums = new Float64Array(count + 1);
      this.heights = new Float64Array(count);
      this.isMeasured = new Uint8Array(count);
    } else {
      this.prefixSums.fill(0);
    }
    for (let i = 0; i < count; i++) {
      this.heights[i] = defaultHeight;
      this.isMeasured[i] = 0;
    }
    this.isPrefixSumDirty = true;
    const currentPoolSize = this.instructionPool.length;
    if (count > currentPoolSize) {
      for (let i = currentPoolSize; i < count; i++) {
        this.instructionPool.push({ y: 0, height: 0, isInViewport: false });
      }
    }
  }

  getLineHeight(index) {
    if (index < 0 || index >= this.lyricCount) return 0;
    this.ensurePrefixSums();
    return this.prefixSums[index + 1] - this.prefixSums[index];
  }

  setLineHeight(index, height) {
    if (index < 0 || index >= this.lyricCount) return;
    if (this.heights[index] !== height || this.isMeasured[index] === 0) {
      this.heights[index] = height;
      this.isMeasured[index] = 1;
      this.isPrefixSumDirty = true;
    }
  }

  updateUnmeasuredHeights(defaultHeight) {
    let changed = false;
    for (let i = 0; i < this.lyricCount; i++) {
      if (this.isMeasured[i] === 0 && this.heights[i] !== defaultHeight) {
        this.heights[i] = defaultHeight;
        changed = true;
      }
    }
    if (changed) this.isPrefixSumDirty = true;
  }

  
  beginFrame(ctx, config) {
    this.ensurePrefixSums();
    const metrics = this.resolveLayoutMetrics(ctx, config);
    const session = {
      isValid: metrics.isValid,
      focalTopY: metrics.focalTopY,
      anchorOffset: metrics.anchorOffset,
      interludeTotalHeight: metrics.interludeTotalHeight,
      activeInterludeAnchor: metrics.activeInterludeAnchor,
      containerHeight: ctx.containerHeight,
      alignPosition: config.alignPosition,
      overscanPx: config.overscanPx,
      bottomLineHeight: ctx.bottomLineHeight
    };
    if (!metrics.isValid) {
      return { bounds: { min: 0, max: 0 }, session };
    }

    const { focalTopY, anchorOffset, interludeTotalHeight, activeInterludeAnchor } = metrics;
    const minOffset = Math.min(0, -focalTopY);
    const basePosWithoutScroll = -focalTopY + ctx.containerHeight * config.alignPosition - anchorOffset;
    let totalContentHeight = this.totalLyricHeight;
    if (activeInterludeAnchor !== undefined) {
      totalContentHeight += interludeTotalHeight;
    }
    const rawMaxOffset = basePosWithoutScroll + totalContentHeight - ctx.containerHeight / 2;
    const maxOffset = Math.max(0, rawMaxOffset);
    return { bounds: { min: minOffset, max: maxOffset }, session };
  }

  commit(session, scrollOffset) {
    this.ensurePrefixSums();
    if (!session.isValid) {
      return this.resetLayoutResult();
    }

    this.layoutResult.lineCount = this.lyricCount;
    const {
      focalTopY, anchorOffset, interludeTotalHeight, activeInterludeAnchor,
      containerHeight, alignPosition, overscanPx, bottomLineHeight
    } = session;

    const viewportStartY = containerHeight * alignPosition - anchorOffset - scrollOffset - focalTopY;
    const motionBuffer = containerHeight * 0.4;
    const viewportTopBound = -overscanPx - motionBuffer;
    const viewportBottomBound = containerHeight + overscanPx + motionBuffer;

    for (let i = 0; i < this.lyricCount; i++) {
      const instruction = this.instructionPool[i];
      let lineY = viewportStartY + this.prefixSums[i];
      const lineH = this.prefixSums[i + 1] - this.prefixSums[i];
      if (activeInterludeAnchor !== undefined && i > activeInterludeAnchor) {
        lineY += interludeTotalHeight;
      }
      instruction.y = lineY;
      instruction.height = lineH;
      instruction.isInViewport = lineY <= viewportBottomBound && lineY + lineH >= viewportTopBound;
    }

    if (activeInterludeAnchor !== undefined) {
      this.layoutResult.hasInterlude = true;
      this.layoutResult.interludeY = viewportStartY + this.prefixSums[activeInterludeAnchor + 1];
    } else {
      this.layoutResult.hasInterlude = false;
      this.layoutResult.interludeY = 0;
    }

    let bottomY = viewportStartY + this.totalLyricHeight;
    if (activeInterludeAnchor !== undefined) {
      bottomY += interludeTotalHeight;
    }
    this.layoutResult.bottomLineY = bottomY;
    this.layoutResult.isBottomLineInViewport =
      bottomY <= viewportBottomBound && bottomY + bottomLineHeight >= viewportTopBound;

    return this.layoutResult;
  }

  static resolveInterludeAnchorIndex(interlude, focalTarget) {
    if (interlude) return interlude.anchorLineIndex;
    if (focalTarget.type === "interlude") return focalTarget.anchorIndex;
    return undefined;
  }

  ensurePrefixSums() {
    if (!this.isPrefixSumDirty) return;
    let sum = 0;
    this.prefixSums[0] = 0;
    for (let i = 0; i < this.lyricCount; i++) {
      sum += this.heights[i];
      this.prefixSums[i + 1] = sum;
    }
    this.totalLyricHeight = sum;
    this.isPrefixSumDirty = false;
  }

  resolveLayoutMetrics(ctx, config) {
    const interludeTotalHeight = ctx.interlude?.totalHeight ?? 0;
    const activeInterludeAnchor = ctx.interlude?.anchorIndex;
    const metrics = {
      isValid: false,
      focalTopY: 0,
      anchorOffset: 0,
      interludeTotalHeight,
      activeInterludeAnchor
    };

    if (
      this.lyricCount === 0 ||
      (ctx.target.type === "line" &&
        (ctx.target.index < 0 || ctx.target.index >= this.lyricCount)) ||
      (ctx.target.type === "interlude" &&
        (ctx.target.anchorIndex < -1 || ctx.target.anchorIndex >= this.lyricCount - 1))
    ) {
      return metrics;
    }

    this.updateFocalMetrics(metrics, ctx.target, interludeTotalHeight, activeInterludeAnchor, ctx.bottomLineHeight, config);
    metrics.isValid = true;
    return metrics;
  }

  updateFocalMetrics(metrics, target, interludeTotalHeight, activeInterludeAnchor, bottomLineHeight, config) {
    let focalTopY = 0;
    let targetHeight = 0;
    if (target.type === "line") {
      focalTopY = this.prefixSums[target.index];
      if (activeInterludeAnchor !== undefined && target.index > activeInterludeAnchor) {
        focalTopY += interludeTotalHeight;
      }
      targetHeight = this.prefixSums[target.index + 1] - this.prefixSums[target.index];
    } else if (target.type === "interlude") {
      focalTopY = this.prefixSums[target.anchorIndex + 1];
      targetHeight = interludeTotalHeight;
    } else if (target.type === "bottom") {
      focalTopY = this.totalLyricHeight;
      if (activeInterludeAnchor !== undefined) {
        focalTopY += interludeTotalHeight;
      }
      targetHeight = bottomLineHeight;
    }
    metrics.focalTopY = focalTopY;
    metrics.anchorOffset = this.calculateAnchorOffset(config.alignAnchor, targetHeight);
  }

  calculateAnchorOffset(alignAnchor, targetHeight) {
    if (targetHeight <= 0) return 0;
    switch (alignAnchor) {
      case "top": return 0;
      case "center": return targetHeight / 2;
      case "bottom": return targetHeight;
    }
    return targetHeight / 2;
  }

  resetLayoutResult() {
    this.layoutResult.lineCount = 0;
    this.layoutResult.hasInterlude = false;
    this.layoutResult.interludeY = 0;
    this.layoutResult.bottomLineY = 0;
    this.layoutResult.isBottomLineInViewport = false;
    for (let i = 0; i < this.instructionPool.length; i++) {
      this.instructionPool[i].isInViewport = false;
      this.instructionPool[i].y = 0;
      this.instructionPool[i].height = 0;
    }
    return this.layoutResult;
  }
}



const LayoutReason = {
  PlaybackTick: "playback-tick",
  Resize: "resize",
  InteractionStart: "interaction-start",
  ContinuousScroll: "continuous-scroll",
  DiscreteScroll: "discrete-scroll",
  InteractionEnd: "interaction-end",
  Seek: "seek",
  NavSeek: "nav-seek",
  RebuildView: "rebuild-view",
  ConfigChange: "config-change"
};

const LayoutReasonStrategyMap = {
  [LayoutReason.PlaybackTick]: { disableStagger: false, resetInterlude: false, snapPosY: false },
  [LayoutReason.InteractionEnd]: { disableStagger: false, resetInterlude: false, snapPosY: false },
  [LayoutReason.ContinuousScroll]: { disableStagger: true, resetInterlude: false, snapPosY: true },
  [LayoutReason.DiscreteScroll]: { disableStagger: true, resetInterlude: false, snapPosY: false },
  [LayoutReason.InteractionStart]: { disableStagger: true, resetInterlude: false, snapPosY: false },
  [LayoutReason.Seek]: { disableStagger: true, resetInterlude: true, snapPosY: false },
  
  
  [LayoutReason.NavSeek]: { disableStagger: false, resetInterlude: true, snapPosY: false },
  [LayoutReason.RebuildView]: { disableStagger: true, resetInterlude: true, snapPosY: false },
  [LayoutReason.Resize]: { disableStagger: true, resetInterlude: false, snapPosY: false },
  [LayoutReason.ConfigChange]: { disableStagger: true, resetInterlude: false, snapPosY: false }
};

const MAX_FRAME_DELTA = 100; 


const NAV_SEEK_HOLD_MS = 1200;











const TOUCH_INTENT_THRESHOLD = 10;

const MOUSE_DRAG_THRESHOLD = 6;

const AUTO_ALIGN_RESUME_DELAY_MS = 500;

const WHEEL_IDLE_TIMEOUT_MS = 150;

const MAX_INERTIA_FRAME_DELTA_MS = 100;

const INERTIA_BASE_FRAME_MS = 1000 / 60;

const INERTIA_MIN_SPEED = 0.05;


class ScrollInteractionEngine {
  constructor(element, callbacks) {
    this.element = element;
    this.callbacks = callbacks;
    this.scrollOffset = 0;
    this.minOffset = 0;
    this.maxOffset = 0;
    this.isAutoAlignSuspended = false;
    this.isTouchScrolled = false;

    
    this.touchState = {
      startY: 0,
      startX: 0,
      lastY: 0,
      startOffset: 0,
      speed: 0,            
      lastTimestamp: 0,
      isIntentConfirmed: false,
      tapCandidate: null,
      tapTimestamp: 0
    };
    
    this.interruptedState = { hadInertia: false, hadTimer: false, wasInteracting: false };
    this.inertiaRafId = 0;
    this.scrollEndTime = undefined;
    this.isInteracting = false;
    this.wheelEndTimeoutId = 0;

    
    this.pointerId = null;
    this.startX = 0;
    this.startY = 0;
    this.lastY = 0;
    this.startTime = 0;
    this.moved = false;
    this.clickCandidateGroup = null;

    this.onTouchStart = this.onTouchStart.bind(this);
    this.onTouchMove = this.onTouchMove.bind(this);
    this.onTouchEnd = this.onTouchEnd.bind(this);
    this.onTouchCancel = this.onTouchCancel.bind(this);
    this.onPointerDown = this.onPointerDown.bind(this);
    this.onPointerMove = this.onPointerMove.bind(this);
    this.onPointerUp = this.onPointerUp.bind(this);
    this.onWheel = this.onWheel.bind(this);

    
    element.addEventListener("touchstart", this.onTouchStart, { passive: false });
    element.addEventListener("touchmove", this.onTouchMove, { passive: false });
    element.addEventListener("touchend", this.onTouchEnd, { passive: false });
    element.addEventListener("touchcancel", this.onTouchCancel, { passive: false });
    
    element.addEventListener("pointerdown", this.onPointerDown);
    window.addEventListener("pointermove", this.onPointerMove, { passive: false });
    window.addEventListener("pointerup", this.onPointerUp);
    window.addEventListener("pointercancel", this.onPointerUp);
    
    element.addEventListener("wheel", this.onWheel, { passive: false });
  }

  dispose() {
    this.element.removeEventListener("touchstart", this.onTouchStart);
    this.element.removeEventListener("touchmove", this.onTouchMove);
    this.element.removeEventListener("touchend", this.onTouchEnd);
    this.element.removeEventListener("touchcancel", this.onTouchCancel);
    this.element.removeEventListener("pointerdown", this.onPointerDown);
    window.removeEventListener("pointermove", this.onPointerMove);
    window.removeEventListener("pointerup", this.onPointerUp);
    window.removeEventListener("pointercancel", this.onPointerUp);
    this.element.removeEventListener("wheel", this.onWheel);
    this.clearTimers();
  }

  updateBoundary(min, max) {
    this.minOffset = Math.min(0, min);
    this.maxOffset = Math.max(0, max);
    this.scrollOffset = this.clampOffset(this.scrollOffset);
    return this.scrollOffset;
  }

  clampOffset(val) {
    const min = Math.min(this.minOffset, this.maxOffset);
    const max = Math.max(this.minOffset, this.maxOffset);
    return Math.min(Math.max(val, min), max);
  }

  resetScroll(offset = 0) {
    this.clearTimers();
    this.scrollEndTime = undefined;
    this.isInteracting = false;
    this.isAutoAlignSuspended = false;
    this.isTouchScrolled = false;
    this.touchState.isIntentConfirmed = false;
    this.touchState.speed = 0;
    this.touchState.tapCandidate = null;
    this.moved = false;
    this.scrollOffset = this.clampOffset(offset);
  }

  
  get canResumeAutoAlign() {
    return (
      this.scrollEndTime !== undefined &&
      performance.now() - this.scrollEndTime >= AUTO_ALIGN_RESUME_DELAY_MS
    );
  }

  startInteraction(type) {
    this.scrollEndTime = undefined;
    if (!this.isInteracting) {
      this.isInteracting = true;
      this.callbacks.onInteractionStart(type);
    }
  }

  endInteraction() {
    this.isInteracting = false;
    this.clearTimers();
    this.scrollEndTime = performance.now();
  }

  
  onTouchStart(evt) {
    
    if (evt.touches.length > 1) {
      const touch = evt.touches[0];
      const state = this.touchState;
      state.startY = touch.screenY;
      state.startX = touch.screenX;
      state.lastY = touch.screenY;
      state.startOffset = this.scrollOffset;
      state.lastTimestamp = performance.now();
      state.speed = 0;
      return;
    }

    this.interruptedState.hadInertia = this.inertiaRafId !== 0;
    this.interruptedState.hadTimer = this.wheelEndTimeoutId !== 0;
    this.interruptedState.wasInteracting = this.isInteracting;

    this.clearTimers();

    const touch = evt.touches[0];
    const state = this.touchState;
    state.startY = touch.screenY;
    state.startX = touch.screenX;
    state.lastY = touch.screenY;
    state.startOffset = this.scrollOffset;
    state.lastTimestamp = performance.now();
    state.speed = 0;
    state.isIntentConfirmed = false;
    state.tapTimestamp = performance.now();
    
    const target = evt.target;
    state.tapCandidate = (target instanceof Element &&
      !target.closest("#controlPill") &&
      !target.closest("#bottomBar"))
      ? target.closest(".lyric-line-wrapper")
      : null;
  }

  onTouchMove(evt) {
    const touch = evt.touches[0];
    const state = this.touchState;

    const deltaY = touch.screenY - state.startY;
    const deltaX = touch.screenX - state.startX;

    if (!state.isIntentConfirmed) {
      
      if (Math.abs(deltaY) > TOUCH_INTENT_THRESHOLD || Math.abs(deltaX) > TOUCH_INTENT_THRESHOLD) {
        state.isIntentConfirmed = true;
        state.tapCandidate = null;
        this.startInteraction("touch");
      } else {
        return;
      }
    }

    if (evt.cancelable) {
      evt.preventDefault();
    }

    const currentY = touch.screenY;
    this.scrollOffset = this.clampOffset(state.startOffset - (currentY - state.startY));

    const now = performance.now();
    const dtMs = now - state.lastTimestamp;
    if (dtMs > 0) {
      state.speed = (currentY - state.lastY) / dtMs;
    }
    state.lastY = currentY;
    state.lastTimestamp = now;

    this.callbacks.onScrollUpdate(true);
  }

  onTouchCancel() {
    const state = this.touchState;

    if (!state.isIntentConfirmed) {
      const { hadInertia, hadTimer, wasInteracting } = this.interruptedState;
      if (hadInertia || hadTimer || wasInteracting) {
        this.endInteraction();
      }
      state.tapCandidate = null;
      return;
    }

    state.speed = 0;
    state.startY = 0;
    state.tapCandidate = null;
    this.endInteraction();
  }

  onTouchEnd(evt) {
    const state = this.touchState;

    
    if (evt.touches.length > 0) {
      const remainingTouch = evt.touches[0];
      state.startY = remainingTouch.screenY;
      state.startX = remainingTouch.screenX;
      state.lastY = remainingTouch.screenY;
      state.startOffset = this.scrollOffset;
      state.lastTimestamp = performance.now();
      state.speed = 0;
      return;
    }

    if (!state.isIntentConfirmed) {
      
      const elapsed = performance.now() - state.tapTimestamp;
      if (state.tapCandidate && elapsed < 400) {
        const candidate = state.tapCandidate;
        state.tapCandidate = null;
        this.callbacks.onLineClick?.(candidate);
        return;
      }
      state.tapCandidate = null;
      const { hadInertia, hadTimer, wasInteracting } = this.interruptedState;
      if (hadInertia || hadTimer || wasInteracting) {
        this.endInteraction();
      }
      return;
    }

    state.isIntentConfirmed = false;

    if (evt.cancelable) {
      
      evt.preventDefault();
    }
    state.startY = 0;

    if (this.inertiaRafId) {
      cancelAnimationFrame(this.inertiaRafId);
      this.inertiaRafId = 0;
    }

    if (Math.abs(state.speed) < 0.1) {
      state.speed = 0;
    }

    if (Math.abs(state.speed) > INERTIA_MIN_SPEED) {
      
      let lastFrameTime = performance.now();

      const onScrollFrame = (time) => {
        const dtMs = time - lastFrameTime;
        lastFrameTime = time;

        if (dtMs <= 0 || dtMs > MAX_INERTIA_FRAME_DELTA_MS) {
          this.inertiaRafId = requestAnimationFrame(onScrollFrame);
          return;
        }

        if (Math.abs(state.speed) > INERTIA_MIN_SPEED) {
          this.scrollOffset -= state.speed * dtMs;
          this.scrollOffset = this.clampOffset(this.scrollOffset);

          const steps = dtMs / INERTIA_BASE_FRAME_MS;
          state.speed *= 0.95 ** steps;

          this.callbacks.onScrollUpdate(true);
          this.inertiaRafId = requestAnimationFrame(onScrollFrame);
        } else {
          this.inertiaRafId = 0;
          this.endInteraction();
        }
      };

      this.inertiaRafId = requestAnimationFrame(onScrollFrame);
    } else {
      this.endInteraction();
    }
  }

  
  onPointerDown(e) {
    if (e.pointerType === "touch") return; 
    if (e.button !== undefined && e.button !== 0) return;
    
    if (e.target.closest("#controlPill") || e.target.closest("#bottomBar")) return;
    this.pointerId = e.pointerId;
    this.startX = e.clientX;
    this.startY = e.clientY;
    this.lastY = e.clientY;
    this.startTime = performance.now();
    this.moved = false;
    
    const groupEl = e.target.closest(".lyric-line-wrapper");
    this.clickCandidateGroup = groupEl || null;
    this.clickCandidateTarget = e.target;
  }

  onPointerMove(e) {
    if (e.pointerType === "touch") return;
    if (this.pointerId === null || e.pointerId !== this.pointerId) return;
    const dy = e.clientY - this.lastY;
    const totalDy = e.clientY - this.startY;
    if (!this.moved && Math.abs(totalDy) < MOUSE_DRAG_THRESHOLD && Math.abs(e.clientX - this.startX) < MOUSE_DRAG_THRESHOLD) {
      return;
    }
    if (!this.moved) {
      this.moved = true;
      this.startInteraction("mouse");
    }
    e.preventDefault();
    
    this.scrollOffset = this.clampOffset(this.scrollOffset - dy);
    this.lastY = e.clientY;
    this.callbacks.onScrollUpdate(true);
  }

  onPointerUp(e) {
    if (e.pointerType === "touch") return;
    if (this.pointerId === null || e.pointerId !== this.pointerId) return;
    const isCancel = e.type === "pointercancel";
    const wasMoved = this.moved;
    const elapsed = performance.now() - this.startTime;
    const candidate = this.clickCandidateGroup;
    this.pointerId = null;
    this.moved = false;
    this.clickCandidateGroup = null;

    if (!isCancel && !wasMoved && elapsed < 400 && candidate) {
      
      this.callbacks.onLineClick?.(candidate);
      return;
    }

    if (wasMoved) {
      this.endInteraction();
    }
  }

  
  onWheel(e) {
    
    if (Math.abs(e.deltaY) < Math.abs(e.deltaX)) return;
    if (e.cancelable) {
      e.preventDefault();
    }
    this.clearTimers();
    this.startInteraction("wheel");
    
    this.scrollOffset += e.deltaMode === WheelEvent.DOM_DELTA_PIXEL ? e.deltaY : e.deltaY * 50;
    this.scrollOffset = this.clampOffset(this.scrollOffset);
    this.callbacks.onScrollUpdate(false);
    this.wheelEndTimeoutId = window.setTimeout(() => {
      this.wheelEndTimeoutId = 0;
      this.endInteraction();
    }, WHEEL_IDLE_TIMEOUT_MS);
  }

  clearTimers() {
    if (this.inertiaRafId) {
      cancelAnimationFrame(this.inertiaRafId);
      this.inertiaRafId = 0;
    }
    if (this.wheelEndTimeoutId) {
      clearTimeout(this.wheelEndTimeoutId);
      this.wheelEndTimeoutId = 0;
    }
  }
}














const SUB_LINE_COLLAPSE_DURATION = 420; 
const SUB_LINE_EASING = [0.22, 1, 0.36, 1]; 
const SUB_LINE_SELECTOR = ".lyric-sub.trans, .lyric-sub.roman, .roman-word, .ruby-word";



function evaluateCubicBezierX(t, x1, y1, x2, y2) {
  if (t <= 0) return 0;
  if (t >= 1) return 1;
  let lo = 0, hi = 1, x = t;
  for (let i = 0; i < 28; i++) {
    const cx = 3 * (1 - x) * (1 - x) * x * x1 + 3 * (1 - x) * x * x * x2 + x * x * x;
    if (Math.abs(cx - t) < 1e-6) break;
    if (cx < t) lo = x; else hi = x;
    x = (lo + hi) / 2;
  }
  return 3 * (1 - x) * (1 - x) * x * y1 + 3 * (1 - x) * x * x * y2 + x * x * x;
}

class SubLineAnimator {
  constructor(player) {
    this.player = player;
    this.progress = { trans: 0, roman: 0, ruby: 0 };   
    this.targets = { trans: 0, roman: 0, ruby: 0 };
    this.startProgress = { trans: 0, roman: 0, ruby: 0 };
    this.elapsed = SUB_LINE_COLLAPSE_DURATION;
    this.active = false;
    this.lineTargets = [];  
    this.lastAnnotateKey = undefined; 
  }

  
  get isAnimating() {
    return this.active;
  }

  



  reset() {
    this.active = false;
    this.elapsed = SUB_LINE_COLLAPSE_DURATION;
    this.lineTargets = [];
    this.lastAnnotateKey = undefined;
    this.player.isSubLineAnimating = false;
  }

  
  retarget() {
    const player = this.player;
    const root = player.element;

    
    if (!this.active) {
      this.progress = {
        trans: root.classList.contains("hide-translation") ? 1 : 0,
        roman: root.classList.contains("hide-romanization") ? 1 : 0,
        ruby: root.classList.contains("hide-ruby") ? 1 : 0
      };
    }
    const newTargets = {
      trans: player.showTranslation ? 0 : 1,
      roman: player.showRomanization ? 0 : 1,
      ruby: player.showRuby ? 0 : 1
    };
    const changed = newTargets.trans !== this.targets.trans ||
      newTargets.roman !== this.targets.roman ||
      newTargets.ruby !== this.targets.ruby;
    this.targets = newTargets;

    
    root.classList.toggle("hide-translation", !player.showTranslation);
    root.classList.toggle("hide-romanization", !player.showRomanization);
    root.classList.toggle("hide-ruby", !player.showRuby);

    if (!changed || player.lyricGroups.length === 0) return;

    const groups = player.lyricGroups;

    
    
    this.clearInlineStyles();

    
    
    
    const annotateKey = `${player.baseFontSize}|${player.size[0]}|${groups.length}`;
    const stateKey = (player.showTranslation ? "1" : "0") +
      (player.showRomanization ? "1" : "0") +
      (player.showRuby ? "1" : "0");
    const needsNaturals = annotateKey !== this.lastAnnotateKey;
    const measureGroups = [];
    let anyAttachedMeasure = false;
    root.classList.add("measuring");
    const wasAttached = [];
    for (let i = 0; i < groups.length; i++) {
      const group = groups[i];
      const attached = !!group.element.parentElement;
      wasAttached.push(attached);
      const cache = group.__subStateHeights;
      const cached = cache && cache.key === annotateKey ? cache.map.get(stateKey) : undefined;
      if (attached) {
        anyAttachedMeasure = true;
      } else if (cached !== undefined && !needsNaturals) {
        continue; 
      } else {
        group.show(); 
        measureGroups.push(i);
      }
    }
    if (needsNaturals) {
      root.classList.remove("hide-translation", "hide-romanization", "hide-ruby");
      void root.offsetWidth; 
      this.annotateNaturals();
      this.lastAnnotateKey = annotateKey;
    }

    
    root.classList.toggle("hide-translation", !player.showTranslation);
    root.classList.toggle("hide-romanization", !player.showRomanization);
    root.classList.toggle("hide-ruby", !player.showRuby);
    if (anyAttachedMeasure || measureGroups.length > 0) {
      void root.offsetWidth;
    }
    this.lineTargets = [];
    let hasHeightDelta = false;
    for (let i = 0; i < groups.length; i++) {
      let h1;
      if (wasAttached[i] || measureGroups.includes(i)) {
        h1 = groups[i].getElement().offsetHeight;
        if (!groups[i].__subStateHeights || groups[i].__subStateHeights.key !== annotateKey) {
          groups[i].__subStateHeights = { key: annotateKey, map: new Map() };
        }
        groups[i].__subStateHeights.map.set(stateKey, h1);
      } else {
        h1 = groups[i].__subStateHeights.map.get(stateKey);
      }
      const h0 = player.getLineHeight(i);
      this.lineTargets.push({ h0, h1 });
      if (Math.abs(h1 - h0) > 0.5) hasHeightDelta = true;
    }

    
    root.classList.remove("measuring");
    for (let i = 0; i < groups.length; i++) {
      if (wasAttached[i] || groups[i].isInSight) {
        this.applyProgressToGroup(groups[i]);
      }
    }
    for (let i = 0; i < groups.length; i++) {
      if (!groups[i].isInSight) groups[i].hide();
    }

    
    if (!hasHeightDelta && !this.hasVisibleAnnotated()) {
      this.progress = { ...this.targets };
      this.active = false;
      this.elapsed = SUB_LINE_COLLAPSE_DURATION;
      player.calcLayout(LayoutReason.ConfigChange);
      return;
    }
    this.startProgress = { ...this.progress };
    this.elapsed = 0;
    this.active = true;
    player.isSubLineAnimating = true;
    player.calcLayout(LayoutReason.ConfigChange);
  }

  
  annotateNaturals() {
    for (const group of this.player.lyricGroups) {
      if (!group.element.parentElement) continue;
      for (const line of [group.mainLine, group.bgLine]) {
        if (!line || !line.element.isConnected) continue;
        this.annotateElement(line.transEl, "trans", 0.3);
        this.annotateElement(line.romanEl, "roman", 0.3);
        for (const el of line.mainEl.querySelectorAll(".roman-word")) {
          this.annotateElement(el, "roman", 1);
        }
        for (const el of line.mainEl.querySelectorAll(".ruby-word")) {
          this.annotateElement(el, "ruby", 1);
        }
      }
    }
  }

  annotateElement(el, type, baseOpacity) {
    if (!el || el.style.display === "none") return;
    
    
    
    
    const cs = getComputedStyle(el);
    const marginTop = parseFloat(cs.marginTop) || 0;
    const marginBottom = parseFloat(cs.marginBottom) || 0;
    const outer = el.offsetHeight + marginTop + marginBottom;
    if (outer <= 0) return;
    el.__subType = type;
    el.__subNatural = outer;
    el.__subBaseOpacity = baseOpacity;
  }

  hasVisibleAnnotated() {
    for (const group of this.player.lyricGroups) {
      if (!group.element.parentElement) continue;
      for (const el of group.element.querySelectorAll(SUB_LINE_SELECTOR)) {
        if (el.__subNatural > 0) return true;
      }
    }
    return false;
  }

  




  clearInlineStyles() {
    for (const group of this.player.lyricGroups) {
      for (const el of group.element.querySelectorAll(SUB_LINE_SELECTOR)) {
        el.style.height = "";
        el.style.minHeight = "";
        el.style.opacity = "";
        el.style.overflow = "";
        el.style.paddingTop = "";
        el.style.paddingBottom = "";
        el.style.marginTop = "";
        el.style.marginBottom = "";
      }
    }
  }

  
  applyProgressToGroup(group) {
    for (const el of group.element.querySelectorAll(SUB_LINE_SELECTOR)) {
      const type = el.__subType;
      if (type === undefined) continue;
      const natural = el.__subNatural;
      if (!(natural > 0)) continue;
      const p = this.progress[type];
      const visible = 1 - p;
      el.style.height = `${(natural * visible).toFixed(2)}px`;
      el.style.minHeight = "0";
      
      
      
      
      el.style.paddingTop = "0";
      el.style.paddingBottom = "0";
      el.style.marginTop = "0";
      el.style.marginBottom = "0";
      
      el.style.opacity = (el.__subBaseOpacity * visible).toFixed(3);
      if (type === "roman" || type === "ruby") el.style.overflow = "hidden";
    }
  }

  
  modelHeightAt(index) {
    if (!this.active) return undefined;
    const target = this.lineTargets[index];
    if (!target || target.frozen) return undefined;
    const t = Math.min(1, this.elapsed / SUB_LINE_COLLAPSE_DURATION);
    const e = evaluateCubicBezierX(t, SUB_LINE_EASING[0], SUB_LINE_EASING[1], SUB_LINE_EASING[2], SUB_LINE_EASING[3]);
    return target.h0 + (target.h1 - target.h0) * e;
  }

  


  noteExternalHeight(index, reportedHeight) {
    if (!this.active) return;
    const target = this.lineTargets[index];
    if (!target || target.frozen) return;
    const model = this.modelHeightAt(index);
    if (model === undefined) return;
    if (Math.abs(reportedHeight - model) > 8) {
      target.frozen = true;
    }
  }

  
  update(deltaMs) {
    if (!this.active) return;
    this.elapsed += Math.min(deltaMs, 100);
    const t = Math.min(1, this.elapsed / SUB_LINE_COLLAPSE_DURATION);
    const e = evaluateCubicBezierX(t, SUB_LINE_EASING[0], SUB_LINE_EASING[1], SUB_LINE_EASING[2], SUB_LINE_EASING[3]);
    this.progress.trans = this.startProgress.trans + (this.targets.trans - this.startProgress.trans) * e;
    this.progress.roman = this.startProgress.roman + (this.targets.roman - this.startProgress.roman) * e;
    this.progress.ruby = this.startProgress.ruby + (this.targets.ruby - this.startProgress.ruby) * e;

    const player = this.player;
    const groups = player.lyricGroups;
    for (let i = 0; i < groups.length; i++) {
      const target = this.lineTargets[i];
      if (!target) continue;
      
      
      if (!target.frozen) {
        player.layoutCalculator.setLineHeight(i, target.h0 + (target.h1 - target.h0) * e);
      }
      
      if (groups[i].element.parentElement) {
        this.applyProgressToGroup(groups[i]);
      }
    }
    player.calcLayout(LayoutReason.ConfigChange);
    if (t >= 1) this.finish();
  }

  
  finish() {
    this.active = false;
    this.elapsed = SUB_LINE_COLLAPSE_DURATION;
    this.progress = { ...this.targets };
    const player = this.player;
    const groups = player.lyricGroups;
    const root = player.element;

    
    
    this.clearInlineStyles();
    root.classList.toggle("hide-translation", !player.showTranslation);
    root.classList.toggle("hide-romanization", !player.showRomanization);
    root.classList.toggle("hide-ruby", !player.showRuby);
    void root.offsetWidth;

    
    
    
    
    const stateKey = (player.showTranslation ? "1" : "0") +
      (player.showRomanization ? "1" : "0") +
      (player.showRuby ? "1" : "0");
    const annotateKey = `${player.baseFontSize}|${player.size[0]}|${groups.length}`;
    for (let i = 0; i < groups.length; i++) {
      const target = this.lineTargets[i];
      if (!target) continue;
      const group = groups[i];
      let h1;
      if (group.element.parentElement) {
        h1 = group.getElement().offsetHeight;
        if (h1 <= 0) h1 = target.h1;
      } else {
        h1 = target.h1;
      }
      player.layoutCalculator.setLineHeight(i, h1);
      if (!group.__subStateHeights || group.__subStateHeights.key !== annotateKey) {
        group.__subStateHeights = { key: annotateKey, map: new Map() };
      }
      group.__subStateHeights.map.set(stateKey, h1);
    }
    player.isSubLineAnimating = false;
    player.calcLayout(LayoutReason.ConfigChange);

    
    for (const group of groups) {
      if (!group.element.parentElement) continue;
      group.mainLine.updateMaskImageSync();
      group.bgLine?.updateMaskImageSync();
    }
  }
}





class LyricPlayer {
  constructor(element) {
    this.element = element;
    this.element.classList.add("amll-lyric-player");

    this.lyricLines = [];
    this.lyricGroups = [];
    this.isNonDynamic = false;
    this.hasDuetLine = false;
    this.hasBottomContent = false;
    this.isPlaying = true;
    this.currentTimeMs = 0;

    
    this.disableSpring = false;      
    this.enableBlur = true;          
    this.enableScale = true;         
    this.hidePassedLines = false;    
    this.swapSubLines = false;       
    this.showTranslation = true;     
    this.showRomanization = true;    
    this.showRuby = true;            
    this.isSubLineAnimating = false; 

    
    this.layoutConfig = {
      alignAnchor: "center",
      
      alignPosition: 0.35,
      overscanPx: 300
    };
    this.frameContext = {
      containerHeight: 0,
      scrollOffset: 0,
      target: { type: "line", index: 0 },
      bottomLineHeight: 0,
      interlude: undefined
    };
    this.visualFrame = {
      latestIndex: 0,
      
      passedBoundary: 0,
      isNarrowViewport: false
    };

    this.size = [0, 0];
    this.posYSpringParams = { ...POS_Y_SPRING_DEFAULT };
    this.currentPosYPolicy = { ...POS_Y_SPRING_DEFAULT };

    this.timeline = new Timeline();
    this.seekDetector = new SeekDetector();
    this.focusController = new FocusController();
    this.layoutCalculator = new LayoutCalculator();
    this.subLineAnimator = new SubLineAnimator(this);
    this.interludeDots = new InterludeDots(document.getElementById("interludeDots"));
    this.bottomLine = new BottomLineEl(this);
    this.interludeDotsSize = [0, 0];

    
    this.bottomLineObserver = new MutationObserver(() => {
      const newHasBottomContent = this.bottomLine.getContentElement().innerHTML.trim().length > 0;
      if (this.hasBottomContent !== newHasBottomContent) {
        if (newHasBottomContent) this.bottomLine.resetPosition();
        this.hasBottomContent = newHasBottomContent;
        this.calcLayout(LayoutReason.ConfigChange);
      }
    });
    this.bottomLineObserver.observe(this.bottomLine.getContentElement(), {
      childList: true, characterData: true, subtree: true
    });

    this.element.appendChild(this.interludeDots.getElement());
    this.element.appendChild(this.bottomLine.getElement());
    this.interludeDots.setTransform(0, 200, true);

    
    this.groupElementMap = new WeakMap();
    
    this.lyricGroupSize = new WeakMap();
    this.resizeObserver = new ResizeObserver((entries) => {
      let shouldRelayout = false;
      for (const entry of entries) {
        if (entry.target === this.element) {
          const rect = entry.contentRect;
          this.size[0] = rect.width;
          this.size[1] = rect.height;
          this.layoutCalculator.updateUnmeasuredHeights(this.defaultLineHeight);
          shouldRelayout = true;
        } else if (entry.target === this.interludeDots.getElement()) {
          const size = this.getEntrySize(entry);
          this.interludeDotsSize[0] = size[0];
          this.interludeDotsSize[1] = size[1];
          shouldRelayout = true;
        } else if (entry.target === this.bottomLine.getElement()) {
          const newSize = this.getEntrySize(entry);
          const oldSize = this.bottomLine.lineSize;
          if (newSize[0] !== oldSize[0] || newSize[1] !== oldSize[1]) {
            this.bottomLine.lineSize = newSize;
            shouldRelayout = true;
          }
        } else {
          const group = this.groupElementMap.get(entry.target);
          if (group) {
            const newSize = this.getEntrySize(entry);
            const isGroupElement = entry.target === group.getElement();
            if (isGroupElement) {
              
              
              
              const oldSize = this.lyricGroupSize.get(group) || [0, 0];
              
              
              
              const dw = Math.abs(newSize[0] - oldSize[0]);
              const dh = Math.abs(newSize[1] - oldSize[1]);
              if (dw > 0.75 || dh > 0.75) {
                this.lyricGroupSize.set(group, newSize);
                const index = this.lyricGroups.indexOf(group);
                if (index !== -1 && newSize[1] > 0) {
                  this.layoutCalculator.setLineHeight(index, newSize[1]);
                }
                if (this.isSubLineAnimating) {
                  
                  
                  
                  
                  
                  if (index !== -1) {
                    this.subLineAnimator.noteExternalHeight(index, newSize[1]);
                  }
                } else {
                  group.onLineSizeChange(newSize);
                  shouldRelayout = true;
                }
              }
            } else {
              
              group.onBgSizeChange?.(newSize);
            }
          }
        }
      }
      if (shouldRelayout && !this.isSubLineAnimating) this.calcLayout(LayoutReason.Resize);
    });
    this.resizeObserver.observe(this.element);
    this.resizeObserver.observe(this.interludeDots.getElement());
    this.resizeObserver.observe(this.bottomLine.getElement());

    this.onResize();

    
    this.scrollEngine = new ScrollInteractionEngine(this.element, {
      onScrollUpdate: (isContinuous) => {
        this.frameContext.scrollOffset = this.scrollEngine.scrollOffset;
        this.calcLayout(isContinuous ? LayoutReason.ContinuousScroll : LayoutReason.DiscreteScroll);
      },
      onInteractionStart: (type) => {
        this.scrollEngine.isAutoAlignSuspended = true;
        this.scrollEngine.isTouchScrolled = type === "touch";
        this.calcLayout(LayoutReason.InteractionStart);
      },
      onLineClick: (groupEl) => this.handleLineClick(groupEl)
    });

    this.seekHandler = null; 
    
    
    this.navSeekUntil = 0;
    this.navJumpLines = 1;
  }

  get defaultLineHeight() {
    return this.size[1] / 5;
  }

  get overscanPx() {
    return this.layoutConfig.overscanPx;
  }

  getLineHeight(index) {
    return this.layoutCalculator.getLineHeight(index);
  }

  getElement() {
    return this.element;
  }

  getIsPlaying() {
    return this.isPlaying;
  }

  getEnableSpring() {
    return !this.disableSpring;
  }

  getEnableScale() {
    return this.enableScale;
  }

  
  setEnableSpring(enable = true) {
    this.disableSpring = !enable;
    this.element.classList.toggle("disable-spring", !enable);
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  setEnableBlur(enable = true) {
    if (this.enableBlur === enable) return;
    this.enableBlur = enable;
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  setEnableScale(enable = true) {
    if (this.enableScale === enable) return;
    this.enableScale = enable;
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  setHidePassedLines(hide = false) {
    this.hidePassedLines = hide;
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  setSwapSubLines(swap = false) {
    if (this.swapSubLines === swap) return;
    this.swapSubLines = swap;
    for (const group of this.lyricGroups) {
      group.mainLine.applySubLinesOrder(swap);
      group.bgLine?.applySubLinesOrder(swap);
    }
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  setShowTranslation(show = true) {
    if (this.showTranslation === show) return;
    this.showTranslation = show;
    this.subLineAnimator.retarget();
  }

  
  setShowRomanization(show = true) {
    if (this.showRomanization === show) return;
    this.showRomanization = show;
    this.subLineAnimator.retarget();
  }

  
  setShowRuby(show = true) {
    if (this.showRuby === show) return;
    this.showRuby = show;
    this.subLineAnimator.retarget();
  }

  getCurrentTime() {
    return this.currentTimeMs;
  }

  getEntrySize(entry) {
    if (entry.borderBoxSize && entry.borderBoxSize.length > 0) {
      return [entry.borderBoxSize[0].inlineSize, entry.borderBoxSize[0].blockSize];
    }
    const target = entry.target;
    if (target && target.getBoundingClientRect) {
      const rect = target.getBoundingClientRect();
      return [rect.width, rect.height];
    }
    return [0, 0];
  }

  onResize() {
    const computedStyles = getComputedStyle(this.element);
    this.baseFontSize = Number.parseFloat(computedStyles.fontSize) || 24;
  }

  
  setLyricLines(lines, initialTime = 0) {
    this.lyricLines = lines;
    this.hasDuetLine = lines.some(l => l.isDuet && !l.isBG);
    this.isNonDynamic = !lines.some(l =>
      !l.isMeta && l.words.some(w => w.endTime > w.startTime)
    );
    this.rebuildLyricView(initialTime);
  }

  rebuildLyricView(initialTime = this.getCurrentTime()) {
    this.scrollEngine.resetScroll(0);
    this.frameContext.scrollOffset = 0;
    this.focusController = new FocusController();

    if (this.hasDuetLine) {
      this.element.classList.add("has-duet");
    } else {
      this.element.classList.remove("has-duet");
    }

    for (const group of this.lyricGroups) {
      group.dispose();
    }
    this.lyricGroups = [];

    this.interludeDots.clearInterlude(true);
    this.resizeObserver.unobserve(this.bottomLine.getElement());

    
    let currentGroup = null;
    for (let i = 0; i < this.lyricLines.length; i++) {
      const line = this.lyricLines[i];
      const lineEl = new LyricLineEl(this, line);
      if (!line.isBG || !currentGroup) {
        currentGroup = new LyricGroup(this, lineEl);
        this.lyricGroups.push(currentGroup);
        this.groupElementMap.set(currentGroup.element, currentGroup);
        this.resizeObserver.observe(currentGroup.element);
      } else {
        currentGroup.addBgLine(lineEl);
      }
    }

    
    this.lyricGroups.sort((a, b) => a.startTime - b.startTime);
    for (let i = 0; i < this.lyricGroups.length; i++) {
      const group = this.lyricGroups[i];
      group.index = i;
    }

    const bounds = this.lyricGroups.map(group => ({
      startTime: group.startTime,
      endTime: group.endTime,
      isMeta: !!(group.mainLine && group.mainLine.getLine() && group.mainLine.getLine().isMeta)
    }));
    for (let i = bounds.length - 1; i >= 0; i--) {
      if (!bounds[i].isMeta) { bounds[i].endTime += 2000; break; }
    }
    this.timeline.setTimeBounds(bounds);

    this.layoutCalculator.initHeights(
      this.lyricGroups.length,
      this.defaultLineHeight
    );

    this.seekDetector.reset();
    this.subLineAnimator.reset();

    this.element.appendChild(this.bottomLine.getElement());
    this.resizeObserver.observe(this.bottomLine.getElement());

    
    
    
    this.element.classList.add("measuring");
    for (const group of this.lyricGroups) {
      group.show();
    }
    void this.element.offsetWidth;
    for (let i = 0; i < this.lyricGroups.length; i++) {
      const group = this.lyricGroups[i];
      
      
      const rect = group.getElement().getBoundingClientRect();
      if (rect.height > 0) {
        this.layoutCalculator.setLineHeight(i, rect.height);
      }
      
      
      
      this.lyricGroupSize.set(group, [rect.width, rect.height]);
      
      
      
      if (group.bgWrapper) {
        const bh = group.bgWrapper.getBoundingClientRect().height;
        if (bh > 0) group.lastBgHeight = bh;
      }
    }
    this.element.classList.remove("measuring");

    this.setLinePosYSpringParams(this.posYSpringParams);

    this.setCurrentTime(initialTime, true);
    this.calcLayout(LayoutReason.RebuildView);

    
    for (const group of this.lyricGroups) {
      if (!group.isInSight) group.hide();
    }
  }

  
  setCurrentTime(time, isSeek = false) {
    if (!Number.isFinite(time)) return;
    const isDetectedSeek = this.seekDetector.detect(time, this.isPlaying);
    this.syncTime(time, isSeek || isDetectedSeek);
  }

  syncTime(time, isSeek) {
    const wasFocusOnInterlude = this.timeline.getSnapshot().isFocusOnInterlude;
    const diff = this.timeline.sync(time, isSeek);
    this.interludeDots.syncClock(time);
    if (!diff.hasChanged) return;

    const snapshot = this.timeline.getSnapshot();

    for (const index of diff.removedHighlighted) {
      this.lyricGroups[index]?.disable();
    }
    if (diff.isTimeJumped) {
      for (const index of snapshot.highlightedGroups) {
        this.lyricGroups[index]?.enable();
      }
    } else {
      for (const index of diff.addedHighlighted) {
        this.lyricGroups[index]?.enable();
      }
    }

    if (diff.isTimeJumped) {
      if (!this.scrollEngine.isTouchScrolled) {
        this.scrollEngine.resetScroll(0);
        this.frameContext.scrollOffset = 0;
      }
    } else if (
      
      
      (diff.isScrollToChanged || wasFocusOnInterlude) &&
      !snapshot.isFocusOnInterlude &&
      snapshot.highlightedGroups.has(snapshot.scrollToIndex) &&
      this.scrollEngine.isAutoAlignSuspended &&
      this.scrollEngine.canResumeAutoAlign &&
      this.lyricGroups[snapshot.scrollToIndex]?.isInViewportRange()
    ) {
      this.scrollEngine.resetScroll(0);
      this.frameContext.scrollOffset = 0;
    }

    if (
      diff.isInterludeChanged ||
      diff.isScrollToChanged ||
      diff.isEndOfSongChanged ||
      diff.isTimeJumped
    ) {
      this.updateSpringParams(
        !!snapshot.activeInterlude,
        diff.isTimeJumped,
        snapshot.isEndOfSong
      );
    }

    let reason = LayoutReason.PlaybackTick;
    if (diff.isTimeJumped) {
      const now = performance.now();
      if (this.navSeekUntil >= now) {
        
        this.navSeekUntil = now + NAV_SEEK_HOLD_MS;
        reason = LayoutReason.NavSeek;
      } else {
        reason = LayoutReason.Seek;
      }
    }
    this.calcLayout(reason);
  }

  
  updateSpringParams(isInterludeActive, isSeeking, isEndOfSong) {
    if (!this.getEnableSpring() || this.lyricGroups.length === 0) return;
    const { scrollToIndex } = this.timeline.getSnapshot();
    const currentGroup = this.lyricGroups[scrollToIndex];
    const prevGroup = this.lyricGroups[scrollToIndex - 1];

    let interval;
    if (currentGroup && prevGroup) {
      interval = currentGroup.startTime - prevGroup.startTime;
    }
    const policy = getPosYSpringPolicy(isSeeking, isInterludeActive, interval, isEndOfSong);
    this.currentPosYPolicy = { ...this.posYSpringParams, ...policy };
    this.setLinePosYSpringParams(policy);
  }

  setLinePosYSpringParams(params) {
    this.posYSpringParams = { ...this.posYSpringParams, ...params };
    this.bottomLine.posY.updateParams(this.posYSpringParams);
    this.interludeDots.posY.updateParams(this.posYSpringParams);
    for (const group of this.lyricGroups) {
      group.posY.updateParams(this.posYSpringParams);
      group.bgSlideY.updateParams(this.posYSpringParams);
    }
  }

  
  calcLayout(reason) {
    const strategy = LayoutReasonStrategyMap[reason];
    const snapshot = this.timeline.getSnapshot();
    const interlude = snapshot.activeInterlude;

    
    let canDisplayInterlude = false;
    if (interlude) {
      canDisplayInterlude = this.interludeDots.setInterlude(
        [interlude.startTime, interlude.endTime],
        snapshot.currentTime,
        strategy.resetInterlude,
        interlude.anchorLineIndex
      );
    } else {
      
      
      this.interludeDots.clearInterlude(!!strategy.resetInterlude);
    }

    
    const focalTarget = this.focusController.resolve(
      snapshot,
      this.lyricGroups.length,
      {
        isAutoAlignSuspended: this.scrollEngine.isAutoAlignSuspended,
        hasBottomContent: this.hasBottomContent,
        canDisplayInterlude
      }
    );

    const fontSize = this.baseFontSize || 24;
    const dotMargin = fontSize * 0.4;
    const totalInterludeHeight = this.interludeDotsSize[1] + dotMargin * 2;

    const ctx = this.frameContext;
    ctx.containerHeight = this.size[1];
    ctx.target = focalTarget;
    ctx.bottomLineHeight = this.bottomLine.lineSize[1] || 0;

    const activeInterludeForLayout = canDisplayInterlude ? interlude : undefined;
    const interludeAnchorIndex = LayoutCalculator.resolveInterludeAnchorIndex(
      activeInterludeForLayout, focalTarget);
    if (interludeAnchorIndex !== undefined) {
      ctx.interlude = ctx.interlude || { totalHeight: 0, anchorIndex: 0 };
      ctx.interlude.totalHeight = totalInterludeHeight;
      ctx.interlude.anchorIndex = interludeAnchorIndex;
    } else {
      ctx.interlude = undefined;
    }

    
    
    const latestIndex = snapshot.latestHighlightedIndex ?? snapshot.scrollToIndex;
    const activeStates = new Array(this.lyricGroups.length);
    for (let i = 0; i < this.lyricGroups.length; i++) {
      activeStates[i] = this.resolveIsActive(i, snapshot, latestIndex);
    }
    this.presyncBgActivationFlips(activeStates);

    const { bounds, session } = this.layoutCalculator.beginFrame(ctx, this.layoutConfig);
    ctx.scrollOffset = this.scrollEngine.updateBoundary(bounds.min, bounds.max);

    const result = this.layoutCalculator.commit(session, ctx.scrollOffset);

    
    if (result.hasInterlude && canDisplayInterlude && interlude) {
      const nextLineIndex = interlude.anchorLineIndex + 1;
      const nextGroup = this.lyricGroups[nextLineIndex];
      const isNextDuet = nextGroup?.mainLine.getLine().isDuet ?? false;
      const targetX = isNextDuet
        ? this.size[0] - this.interludeDotsSize[0]
        : 0;
      this.interludeDots.setTransform(
        targetX,
        result.interludeY + dotMargin,
        strategy.snapPosY || !this.getEnableSpring()
      );
    }

    
    const visual = this.visualFrame;
    visual.latestIndex = snapshot.latestHighlightedIndex ?? snapshot.scrollToIndex;
    visual.passedBoundary = interlude
      ? interlude.anchorLineIndex + 1
      : snapshot.scrollToIndex;
    visual.isNarrowViewport = this.size[0] <= 1024;

    
    
    let windowEarliest = snapshot.scrollToIndex;
    let windowLatest = snapshot.scrollToIndex;
    for (const index of snapshot.highlightedGroups) {
      if (index < windowEarliest) windowEarliest = index;
      if (index > windowLatest) windowLatest = index;
    }
    const brightnessWindowFrom = windowEarliest - BRIGHTNESS_WINDOW_LINES;
    const brightnessWindowTo = windowLatest + BRIGHTNESS_WINDOW_LINES;

    const activeCount = result.lineCount;

    let delay = 0;
    let baseDelay = strategy.disableStagger ? 0 : 0.05;
    if (reason === LayoutReason.NavSeek && this.navJumpLines > 2) {
      baseDelay = Math.max(0.018, 0.05 / Math.sqrt(this.navJumpLines));
    }

    for (let i = 0; i < activeCount; i++) {
      const group = this.lyricGroups[i];
      const instruction = result.lineInstructions[i];
      const curPos = instruction.y;
      const isInViewport = instruction.isInViewport;
      const isActive = i < activeStates.length ? activeStates[i] : this.resolveIsActive(i, snapshot, visual.latestIndex);

      group.setTransform(
        curPos,
        strategy.snapPosY,
        delay,
        isActive,
        this.resolveOpacity(i, isInViewport, snapshot),
        this.resolveBlurLevel(i, isActive, isInViewport, snapshot),
        i >= brightnessWindowFrom && i <= brightnessWindowTo
      );
      const lineH = instruction.height;
      if (curPos + lineH >= 0) {
        delay += baseDelay;
        if (i >= snapshot.scrollToIndex) {
          baseDelay /= 1.05;
        }
      }
    }
    const isBottomFocused = focalTarget.type === "bottom";
    this.bottomLine.setFocused(isBottomFocused);
    this.bottomLine.setTransform(
      result.bottomLineY,
      this.resolveBlurLevel(activeCount, isBottomFocused, result.isBottomLineInViewport, snapshot),
      strategy.snapPosY,
      delay
    );
  }

  resolveIsActive(index, snapshot, latestIndex) {
    const latest = latestIndex ?? this.visualFrame.latestIndex;
    return (
      snapshot.highlightedGroups.has(index) ||
      (index >= snapshot.scrollToIndex && index < latest)
    );
  }

  









  presyncBgActivationFlips(activeStates) {
    for (let i = 0; i < this.lyricGroups.length; i++) {
      const group = this.lyricGroups[i];
      if (!group.bgWrapper) continue;
      const willActive = activeStates[i] || !!group.bgAlwaysActive;
      const isBgActive = group.bgWrapper.classList.contains("active");
      if (willActive === isBgActive) continue;
      group.bgWrapper.classList.toggle("active", willActive);
      group.lastIsActive = willActive;
      if (!group.element.parentElement) {
        
        
        
        
        
        
        this.element.insertBefore(group.element, this.bottomLine.getElement());
        const r = group.element.getBoundingClientRect();
        this.resizeObserver.unobserve(group.element);
        group.element.remove();
        if (r.height > 0) {
          this.layoutCalculator.setLineHeight(i, r.height);
          this.lyricGroupSize.set(group, [r.width, r.height]);
        }
        continue;
      }
      
      
      const rect = group.element.getBoundingClientRect();
      if (rect.height <= 0) continue;
      this.layoutCalculator.setLineHeight(i, rect.height);
      this.lyricGroupSize.set(group, [rect.width, rect.height]);
    }
  }

  resolveOpacity(index, isInViewport, snapshot) {
    
    if (!isInViewport) return 0;

    
    if (
      this.hidePassedLines &&
      this.isPlaying &&
      index < this.visualFrame.passedBoundary
    ) {
      return 1e-4;
    }

    if (snapshot.highlightedGroups.has(index)) return 0.85;
    const metaGroup = this.lyricGroups[index];
    const metaLine = metaGroup && metaGroup.mainLine && metaGroup.mainLine.getLine ? metaGroup.mainLine.getLine() : null;
    if (metaLine && metaLine.isMeta) return 0.2;
    return this.isNonDynamic ? 0.2 : 1;
  }

  resolveBlurLevel(index, isFocused, isInViewport, snapshot) {
    if (!this.enableBlur) return 0;

    
    if (!isInViewport) return 0;

    
    if (this.scrollEngine.isTouchScrolled || isFocused) return 0;

    const scrollToIndex = snapshot.scrollToIndex;
    const distance =
      index < scrollToIndex
        ? Math.abs(scrollToIndex - index) + 1
        : Math.abs(index - this.visualFrame.latestIndex);
    const level = 1 + distance;
    return this.visualFrame.isNarrowViewport ? level * 0.8 : level;
  }

  
  pause() {
    this.isPlaying = false;
    this.element.classList.remove("playing");
    this.interludeDots.pause();
    for (const group of this.lyricGroups) {
      group.mainLine.pause();
      group.bgLine?.pause();
    }
    this.calcLayout(LayoutReason.ConfigChange);
  }

  resume() {
    this.isPlaying = true;
    this.element.classList.add("playing");
    this.interludeDots.resume();
    for (const group of this.lyricGroups) {
      group.mainLine.resume();
      group.bgLine?.resume();
    }
    this.calcLayout(LayoutReason.ConfigChange);
  }

  
  update(deltaMs) {
    const delta = Math.min(deltaMs, MAX_FRAME_DELTA) / 1000;
    
    this.subLineAnimator.update(deltaMs);
    this.bottomLine.update(delta);
    this.interludeDots.update(delta);
    for (const group of this.lyricGroups) {
      group.update(delta);
    }
    for (const group of this.lyricGroups) {
      group.commitChanges();
    }
    this.bottomLine.commitChanges();
  }

  
  handleLineClick(groupEl) {
    const group = this.groupElementMap.get(groupEl);
    const creatorEl = this.clickCandidateTarget && this.clickCandidateTarget.closest ? this.clickCandidateTarget.closest(".lyric-creator") : null;
    this.clickCandidateTarget = null;
    if (creatorEl) return;
    if (!group || !this.seekHandler) return;
    const line = group.mainLine.getLine();
    // 暂无歌词页: 点歌词行不跳播放时间, 点引导元信息行则让父页去换一次性授权链接
    if (typeof noLyricMode !== "undefined" && noLyricMode) {
      if (line.isMeta) window.parent.postMessage({ type: "openGuide" }, "/");
      return;
    }
    
    
    this.scrollEngine.resetScroll(0);
    this.frameContext.scrollOffset = 0;
    
    
    
    let targetTime = line.startTime;
    for (const w of line.words) {
      if (w.word.trim().length > 0 && w.startTime > 0) {
        targetTime = w.startTime;
        break;
      }
    }
    
    const now = this.currentTimeMs;
    if (now >= targetTime && now < line.endTime) {
      for (const w of line.words) {
        if (w.startTime > now) { targetTime = w.startTime; break; }
        targetTime = Math.max(targetTime, w.startTime);
      }
    }
    
    this.navJumpLines = Math.max(
      1,
      Math.abs(this.lyricGroups.indexOf(group) - this.timeline.getSnapshot().scrollToIndex),
    );
    this.navSeekUntil = performance.now() + NAV_SEEK_HOLD_MS;
    this.seekHandler(Math.max(0, targetTime));
  }

  
  remeasureAllLines() {
    if (this.lyricGroups.length === 0) return;
    
    
    this.element.classList.add("measuring");
    for (let i = 0; i < this.lyricGroups.length; i++) {
      const group = this.lyricGroups[i];
      if (!group.element.parentElement) group.show();
    }
    void this.element.offsetWidth;
    for (let i = 0; i < this.lyricGroups.length; i++) {
      const group = this.lyricGroups[i];
      
      const rect = group.getElement().getBoundingClientRect();
      if (rect.height > 0) {
        this.layoutCalculator.setLineHeight(i, rect.height);
        this.lyricGroupSize.set(group, [rect.width, rect.height]);
      }
      if (group.bgWrapper) {
        const bh = group.bgWrapper.getBoundingClientRect().height;
        if (bh > 0) group.lastBgHeight = bh;
      }
      group.mainLine.updateMaskImageSync();
      group.bgLine?.updateMaskImageSync();
    }
    this.element.classList.remove("measuring");
    for (const group of this.lyricGroups) {
      if (!group.isInSight) group.hide();
    }
    this.calcLayout(LayoutReason.Resize);
  }

  dispose() {
    this.scrollEngine.dispose();
    this.resizeObserver.disconnect();
    this.bottomLineObserver.disconnect();
    this.interludeDots.dispose();
    for (const group of this.lyricGroups) group.dispose();
    this.element.remove();
  }
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

const playerEl = document.querySelector(".amll-lyric-player");
const player = new LyricPlayer(playerEl);
window.__ttmlPlayer = player;

player.seekHandler = (ms) => {
  window.parent.postMessage({ type: "seekAudio", time: Math.max(0, ms / 1000) }, "/");
};

function matchTranslationPool(lines) {
  if (typeof tlyricData === "undefined" || !tlyricData || tlyricData.length === 0) return;
  let potentialPairs = [];
  lines.forEach((line, lineIdx) => {
    if (line.isBG || line.translatedLyric || line.isMeta || line.startTime < 0) return;
    tlyricData.forEach((trans, transIdx) => {
      let diff = Math.abs(line.startTime - trans.time * 1000);
      if (diff < 4000) {
        potentialPairs.push({ lineIdx, transIdx, diff, text: trans.text });
      }
    });
  });
  potentialPairs.sort((a, b) => a.diff - b.diff);
  let matchedLines = new Set();
  let matchedTrans = new Set();
  potentialPairs.forEach(pair => {
    if (matchedLines.has(pair.lineIdx) || matchedTrans.has(pair.transIdx)) return;
    lines[pair.lineIdx].translatedLyric = pair.text;
    matchedLines.add(pair.lineIdx);
    matchedTrans.add(pair.transIdx);
  });
}

function renderBottomLine(metadata, empty) {
  const el = player.bottomLine.getContentElement();
  if (empty) {
    el.innerHTML = "<div>" + escapeHtml("暂无歌词") + "</div>";
    return;
  }
  const collect = (key) => {
    const out = [];
    metadata.forEach(([k, v]) => { if (k === key && v) out.push(v); });
    return out;
  };
  const songwriters = collect("songwriter");
  const authorLogin = collect("ttmlAuthorGithubLogin")[0] || "";
  const authorGithub = collect("ttmlAuthorGithub")[0] || "";
  const ttmlAuthor = collect("ttmlAuthor")[0] || "";
  let producer = "";
  if (authorLogin && authorGithub && authorGithub !== authorLogin) producer = authorLogin + " (" + authorGithub + ")";
  else producer = authorLogin || authorGithub || ttmlAuthor;
  let html = "";
  if ((typeof showMeta === "undefined" || showMeta !== false) && songwriters.length > 0) {
    html += "<div>" + escapeHtml("词曲: " + songwriters.join(" / ")) + "</div>";
  }
  if ((typeof showContributors === "undefined" || showContributors !== false) && producer) {
    html += "<div>" + escapeHtml("歌词制作: " + producer) + "</div>";
  }
  el.innerHTML = html;
}

const initialTransOn = document.body.classList.contains("show-trans");
player.setShowTranslation(initialTransOn);

let timeMs = 0;
let lastReportedKey = "";

(function loadLyricData() {
  const raw = (typeof ttmlData !== "undefined") ? String(ttmlData || "") : "";
  let lines = [];
  let metadata = [];
  if (raw.trim()) {
    try {
      const parsed = parseTTML(raw);
      lines = optimizeLyricLines(parsed.lyricLines || []);
      metadata = parsed.metadata || [];
    } catch (e) {
      lines = [];
    }
  }
  player.timeline.lrcMode = /itunes:origin="lrc"/.test(raw);
  matchTranslationPool(lines);
  player.setLyricLines(lines, 0);
  renderBottomLine(metadata, lines.length === 0);
  player.resume();
  lastReportedKey = "";
})();

let smtcPendingKey = "";
let smtcPendingPayload = null;
let smtcTimer = 0;

function buildSmtcSnapshot() {
  const snap = player.timeline.getSnapshot();
  const lines = [];
  for (const id of player.timeline.playingGroupsSet) {
    const group = player.lyricGroups[id];
    if (!group || !group.mainLine) continue;
    const line = group.mainLine.getLine();
    if (!line || line.isBG) continue;
    const text = line.words.map(w => w.word).join("")
      .replace(/\u0001\d+\u0001/g, "")
      .replace(/<[^>]*>/g, "")
      .replace(/[\u0000-\u001f\u007f-\u009f]/g, "")
      .trim();
    if (text) lines.push({ text: text, start: line.startTime });
  }
  lines.sort((a, b) => a.start - b.start);
  const inter = snap.activeInterlude;
  const interlude = !!(inter && inter.endTime - inter.startTime >= 8000);
  return {
    key: JSON.stringify({ lines: lines.map(l => l.text), interlude, end: !!snap.isEndOfSong }),
    payload: {
      type: "smtcState",
      lines: lines.map(l => ({ text: l.text, start: l.start })),
      interlude: interlude,
      end: !!snap.isEndOfSong
    }
  };
}

function reportSmtcState() {
  const snap = buildSmtcSnapshot();
  if (snap.key === lastReportedKey) {
    if (smtcTimer) { clearTimeout(smtcTimer); smtcTimer = 0; }
    smtcPendingKey = "";
    smtcPendingPayload = null;
    return;
  }
  if (snap.key === smtcPendingKey) return;
  smtcPendingKey = snap.key;
  smtcPendingPayload = snap.payload;
  if (smtcTimer) clearTimeout(smtcTimer);
  smtcTimer = setTimeout(() => {
    smtcTimer = 0;
    if (!smtcPendingPayload) return;
    lastReportedKey = smtcPendingKey;
    smtcPendingKey = "";
    const payload = smtcPendingPayload;
    smtcPendingPayload = null;
    window.parent.postMessage(payload, "/");
  }, 180);
}

let lastFrameTime = performance.now();
function rafLoop() {
  const frameStart = performance.now();
  const delta = Math.max(0, frameStart - lastFrameTime);
  lastFrameTime = frameStart;
  player.currentTimeMs = timeMs;
  player.setCurrentTime(timeMs);
  player.update(delta);
  reportSmtcState();
  requestAnimationFrame(rafLoop);
}
requestAnimationFrame(rafLoop);
setInterval(() => {
  if (!Number.isFinite(timeMs)) return;
  player.setCurrentTime(timeMs);
  reportSmtcState();
}, 250);

window.addEventListener("message", (e) => {
  if (e.source !== window.parent) return;
  if (!e.data || typeof e.data !== "object") return;
  if (e.data.type === "playTimeResponse" && Number.isFinite(Number(e.data.time))) {
    timeMs = Number(e.data.time) * 1000;
  }
  if (e.data.type === "toggleTrans") {
    player.setShowTranslation(!!e.data.visible);
  }
  if (e.data.type === "setPlaying") {
    if (e.data.playing) player.resume();
    else player.pause();
  }
  if (e.data.type === "updateColor") {
    const c = e.data.color;
    if (typeof c !== "string" || !/^#[0-9a-fA-F]{3,8}$/.test(c.trim())) return;
    const v = c.trim();
    document.documentElement.style.setProperty("--active-color", v);
    const m6 = /^#([0-9a-fA-F]{6})/.exec(v);
    const m3 = /^#([0-9a-fA-F]{3})$/.exec(v);
    let rgb = null;
    if (m6) { const n = parseInt(m6[1], 16); rgb = [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
    else if (m3) { const h = m3[1]; rgb = [parseInt(h[0] + h[0], 16), parseInt(h[1] + h[1], 16), parseInt(h[2] + h[2], 16)]; }
    if (rgb) document.documentElement.style.setProperty("--active-rgb", rgb.join(", "));
  }
  if (e.data.type === "updateTransColor") {
    const c = e.data.color;
    if (typeof c !== "string" || !/^#[0-9a-fA-F]{3,8}$/.test(c.trim())) return;
    document.documentElement.style.setProperty("--trans-color", c.trim());
  }
  if (e.data.type === "updateIdleColor") {
    const c = e.data.color;
    if (typeof c !== "string" || !/^#[0-9a-fA-F]{3,8}$/.test(c.trim())) return;
    document.documentElement.style.setProperty("--idle-color", c.trim());
  }
  if (e.data.type === "updateTransIdleColor") {
    const c = e.data.color;
    if (typeof c !== "string" || !/^#[0-9a-fA-F]{3,8}$/.test(c.trim())) return;
    document.documentElement.style.setProperty("--trans-idle-color", c.trim());
  }
});

setInterval(() => window.parent.postMessage({ type: "getPlayTime", id: "frs" }, "/"), 10);
window.addEventListener("click", () => { window.parent.postMessage({ type: "iframeClick" }, "/"); });
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => player.remeasureAllLines());
